"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[5706],{27997:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"flash-info-2025-05","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-05","source":"@site/blog/2025/2025-02-27-flash-info-05.md","title":"Flash Info de l\'IDRIS n\xb02025-05","description":"Sommaire :","date":"2025-02-27T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2025-05","title":"Flash Info de l\'IDRIS n\xb02025-05","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02025-04","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-04"}},"content":"Sommaire :\\n\\n* Hackathon GPU HPC et IA : plus que quelques jours pour candidater\\n* Panoram\'IA : rendez-vous vendredi 28/02 \xe0 10h\\n* CEEMS : un outil de mesure \xe9nerg\xe9tique sur Jean Zay\\n* Formations IDRIS\\n\\n--------------------------------------------------------------------\\n\\n* Hackathon GPU HPC et IA : plus que quelques jours pour candidater\\n\\nNous vous rappelons que la date limite d\'inscription pour notre hackathon GPU HPC et IA est fix\xe9e\\nau 4 mars. Pour rappel, cet \xe9v\xe9nement, organis\xe9 conjointement avec NVIDIA, aura lieu le 13 mai\\n(\xe0 distance) et les 20, 21 et 22 mai (dans les locaux de l\'IDRIS).\\n\\nL\'inscription se fait via la page de l\'\xe9v\xe8nement (en anglais) :\\nhttps://www.openhackathons.org/s/siteevent/a0CUP00000sO9LV2A0/se000364.\\n\\n* Panoram\'IA : rendez-vous vendredi 28/02 \xe0 10h\\n\\nL\'assistance de l\'IDRIS vous propose le vendredi matin 28/02 \xe0 10h, un direct de son \xe9mission\\n\\"Panoram\'IA\\". Cette \xe9mission se fera en compagnie de notre invit\xe9 J\xe9r\xf4me Louradour qui nous\\nfera un retour d\'exp\xe9rience sur le pretraining de Lucie sur notre supercalculateur Jean Zay.\\nLe direct ainsi que les rediffusions sont disponibles sur notre cha\xeene Youtube \\"Un oeil sur l\'IDRIS\\" :\\nhttps://www.youtube.com/@idriscnrs.\\n\\n* CEEMS : un outil de mesure \xe9nerg\xe9tique sur Jean Zay\\n\\nComme annonc\xe9 lors du dernier comit\xe9 des utilisateurs, l\'outil CEEMS de mesure de l\'\xe9nergie est\\nd\xe9sormais disponible sur Jean Zay : voir la page http://www.idris.fr/jean-zay/jean-zay-doc-energie.html\\npour plus d\'informations.\\n\\n* Formations IDRIS\\n\\nPensez \xe0 vous inscrire d\xe8s maintenant aux formations IDRIS planifi\xe9es sur les prochains mois :\\n\\n- MPI, du 18 au 21 mars\\n- OpenMP, du 26 au 28 mars\\n- C++ Scientifique Moderne, du 9 au 11 avril\\n- Introduction \xe0 OpenACC et OpenMP GPU, du 16 au 18 avril\\n- Programmation hybride MPI/OpenMP, du 5 au 6 juin\\n- Workshop Jean Zay, du 12 au 13 juin\\n- OpenMP/MPI, du 16 au 20 juin\\n\\nPour plus d\'informations sur le catalogue des formations de l\'IDRIS et les modalit\xe9s d\'inscription :\\nhttp://www.idris.fr/formations/catalogue.html."},{"id":"flash-info-2025-04","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-04","source":"@site/blog/2025/2025-02-10-flash-info-04.md","title":"Flash Info de l\'IDRIS n\xb02025-04","description":"Webinaire d\'information \\"Se pr\xe9parer au hackathon\\"","date":"2025-02-10T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2025-04","title":"Flash Info de l\'IDRIS n\xb02025-04","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02025-05","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-05"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02025-03","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-03"}},"content":"Webinaire d\'information \\"Se pr\xe9parer au hackathon\\"\\n\\n[English version below]\\n\\nL\'IDRIS organise son 5\xe8me Hackathon (https://www.openhackathons.org/s/siteevent/a0CUP00000sO9LV2A0/se000364) du 13 au 22 mai 2025 et nous sommes \xe0 la recherche d\'\xe9quipes int\xe9ress\xe9es pour participer (date limite d\'inscription : 4 mars).\\n\\nQu\'est-ce qu\'un hackathon ? Il s\'agit d\'un \xe9v\xe8nement d\xe9di\xe9 aux d\xe9veloppeurs de codes scientifiques qui vise \xe0 aider les chercheurs et ing\xe9nieurs \xe0 optimiser, acc\xe9l\xe9rer et faire passer \xe0 l\'\xe9chelle leurs applications HPC ou IA sur Jean Zay. Pour cela, vous serez accompagn\xe9s de mentors experts en programmation dont les conseils permettront de booster vos projets HPC ou IA.\\n\\nCette ann\xe9e NVIDIA vous invite \xe0 un webinaire d\'information \\"Se pr\xe9parer au hackathon\\" centr\xe9 sur les applications IA, avec la participation de l\'IDRIS :\\n\\n     Rejoignez-nous le 18 f\xe9vrier \xe0 11h pour d\xe9couvrir comment profiter au mieux de cette opportunit\xe9.\\n     \\n     En participant au s\xe9minaire, vous pourrez :\\n      - obtenir une vue d\'ensemble du prochain hackathon de l\'IDRIS (https://www.openhackathons.org/s/siteevent/a0CUP00000sO9LV2A0/se000364) et de la mani\xe8re dont il peut b\xe9n\xe9ficier \xe0 votre recherche en IA ;\\n      - d\xe9couvrir des cas d\'utilisation IA ayant b\xe9n\xe9fici\xe9 des hackathons pr\xe9c\xe9dents ;\\n      - comprendre comment profiter de Jean Zay pour vos projets d\'IA ;\\n      - rencontrer des sp\xe9cialistes en IA de NVIDIA pour \xe9changer en priv\xe9 sur votre projet.\\n     \\n     Le nombre de places est limit\xe9, inscrivez-vous maintenant : https://bit.ly/IdrisGHR.\\n     \\n     Pour un aper\xe7u des projets qui ont b\xe9n\xe9fici\xe9 du hackathon de l\'ann\xe9e pass\xe9e, vous pouvez lire le r\xe9capitulatif du Hackathon IDRIS 2024 : https://www.openhackathons.org/s/article/IDRIS-Contributing-to-the-Excellence-of-Scientific-Research.\\n     \\n     Nous esp\xe9rons que vous participerez pour en savoir plus et recevoir un support personnalis\xe9.\\n\\nSi vous avez des questions, n\'h\xe9sitez pas \xe0 contacter events@openhackathons.org (en anglais).\\n\\n------------------------------------\\n\\nIDRIS is hosting its fifth IDRIS Open Hackathon (https://www.openhackathons.org/s/siteevent/a0CUP00000sO9LV2A0/se000364) from May 13 to May 22, 2025 and we are actively seeking applications (deadline: March 4th).\\n\\nIf you are not familiar, this hands-on coding event helps researchers and engineers to optimize, accelerate, and scale their HPC and AI applications on Jean Zay by pairing them with expert programming mentors whose guidance can take your HPC and AI projects to the next level.\\n\\nThis year NVIDIA invites you to an informational webinar \u201cGetting Hackathon Ready\u201d focused on AI applications, with the participation of IDRIS:\\n\\n     Join us on February 18th, 11AM CET to learn more about how to participate in this unique opportunity.\\n     \\n     By attending the webinar, you will:\\n      - Get an overview of the upcoming IDRIS Open Hackathon (https://www.openhackathons.org/s/siteevent/a0CUP00000sO9LV2A0/se000364) and how it can benefit your AI research;\\n      - Examine AI use cases advanced at previous hackathons;\\n      - Understand how Jean Zay can support your AI projects; and\\n      - Get the chance to meet AI specialists from NVIDIA for a private consultation on your project.\\n     \\n     Space is limited, sign up now: https://bit.ly/IdrisGHR.\\n     \\n     For a glimpse of the projects that benefited from attending last year\u2019s event, read the 2024 IDRIS Open Hackathon recap: https://www.openhackathons.org/s/article/IDRIS-Contributing-to-the-Excellence-of-Scientific-Research.\\n     \\n     We hope you will join us to learn more and receive personalized expert support.\\n\\nShould you have any questions, please contact events@openhackathons.org."},{"id":"flash-info-2025-03","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-03","source":"@site/blog/2025/2025-01-22-flash-info-03.md","title":"Flash Info de l\'IDRIS n\xb02025-03","description":"Migration de l\'espace DSDIR sur Lustre","date":"2025-01-22T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2025-03","title":"Flash Info de l\'IDRIS n\xb02025-03","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02025-04","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-04"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02025-02","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-02"}},"content":"Migration de l\'espace DSDIR sur Lustre\\n\\n[English version below]\\n\\nBonjour,\\n\\nLors de la maintenance du 21 janvier 2025, la variable d\'environnement DSDIR a \xe9t\xe9 modifi\xe9e et\\nredirige maintenant vers un nouvel espace de stockage Lustre : \\"/lustre/fsmisc/dataset\\".\\n\\nL\'ensemble des bases de donn\xe9es et mod\xe8les t\xe9l\xe9charg\xe9s dans le DSDIR depuis les d\xe9buts de Jean Zay\\ny a \xe9t\xe9 migr\xe9. Ce nouvel espace est accessible depuis l\'ensemble des noeuds de Jean Zay, y compris\\nles noeuds de la nouvelle extension H100.\\n\\nC\'est ce nouvel espace qui sera dor\xe9navant utilis\xe9 pour les t\xe9l\xe9chargements de datasets ou mod\xe8les\\npublics. Les anciens espaces disques \\"/gpfsdsdir/dataset\\" et \\"/gpfsdswork/dataset\\" sont d\xe9sormais\\nd\xe9pr\xe9ci\xe9s et ne seront plus accessibles \xe0 partir de la fin du mois de janvier.\\n\\nSi vous utilisez d\xe9j\xe0 la variable d\'environnement DSDIR dans vos scripts, la migration des donn\xe9es\\nn\'aura pas d\'impact sur vos ex\xe9cutions. Mais si vous utilisez des chemins explicites, il faudra penser\\n\xe0 les modifier. Nous vous invitons \xe0 cette occasion \xe0 basculer sur un usage syst\xe9matique de la\\nvariable DSDIR, comme dans le script suivant par exemple :\\n\\n\'\'\'\\nimport os\\nfrom datasets import load_dataset\\ndataset = load_dataset(os.environ[\'DSDIR\']+\\"/HuggingFace/wikimedia/structured-wikipedia\\")\\n\'\'\'\\n\\nPour rappel, le DSDIR est un espace disque d\xe9di\xe9 au stockage de bases de donn\xe9es ou mod\xe8les publics\\nn\xe9cessaires \xe0 l\'utilisation d\'outils de l\'Intelligence Artificielle. Il est visible par l\'ensemble des\\nutilisateurs de Jean Zay. Pour plus d\'information :\\nhttp://www.idris.fr/jean-zay/cpu/jean-zay-cpu-calculateurs-disques.html#le_dsdir\\n\\nN\'h\xe9sitez pas \xe0 contacter l\'assistance \xe0 assist@idris.fr si vous rencontrez des probl\xe8mes.\\n\\nBien cordialement,\\nL\'\xe9quipe assistance IDRIS\\n\\n--------------------------------------------------------------------\\n\\nHello,\\n\\nDuring the maintenance on January 21, 2025, the DSDIR environment variable was modified and now points\\nto a new Lustre storage space: \\"/lustre/fsmisc/dataset\\".\\n\\nAll databases and models downloaded to DSDIR since the beginning of Jean Zay have been migrated to this\\nnew space. This new space is accessible from all Jean Zay nodes, including the nodes of the new H100\\nextension.\\n\\nThis new space will now be used for downloading public datasets or models. The old disk spaces\\n\\"/gpfsdsdir/dataset\\" and \\"/gpfsdswork/dataset\\" are now deprecated and will no longer be accessible as\\nof the end of January.\\n\\nIf you are already using the DSDIR environment variable in your scripts, the data migration will have\\nno impact on your runs. However, if you are using hardcoded paths, you will need to update them. We\\ninvite you to take this opportunity to switch to systematic use of the DSDIR variable, as in the\\nfollowing script for example:\\n\\n\'\'\'\\nimport os\\nfrom datasets import load_dataset\\ndataset = load_dataset(os.environ[\'DSDIR\']+\\"/HuggingFace/wikimedia/structured-wikipedia\\")\\n\'\'\'\\n\\nAs a reminder, DSDIR is a dedicated disk space for storing public databases or models needed for the\\nuse of Artificial Intelligence tools. It is visible to all Jean Zay users. For more information:\\nhttp://www.idris.fr/eng/jean-zay/cpu/jean-zay-cpu-calculateurs-disques-eng.html#the_dsdir\\n\\nPlease do not hesitate to contact the support team at assist@idris.fr if you encounter any issue.\\n\\nBest regards,\\nThe IDRIS support team"},{"id":"flash-info-2025-02","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-02","source":"@site/blog/2025/2025-01-15-flash-info-02.md","title":"Flash Info de l\'IDRIS n\xb02025-02","description":"Hackathon GPU HPC et IA \xe0 l\'IDRIS en mai 2025","date":"2025-01-15T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2025-02","title":"Flash Info de l\'IDRIS n\xb02025-02","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02025-03","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-03"},"nextItem":{"title":"Hackathon GPU HPC et IA 2025 \xe0 l\'IDRIS","permalink":"/documentation/idris-documentation-docusaurus/blog/hackthon-idris-nvidia-2025"}},"content":"Hackathon GPU HPC et IA \xe0 l\'IDRIS en mai 2025\\n\\nPour la cinqui\xe8me ann\xe9e cons\xe9cutive, l\'IDRIS organise, conjointement avec NVIDIA, un hackathon GPU HPC et IA.\\n\\nIl aura lieu le 13 mai (\xe0 distance) et les 20, 21 et 22 mai 2025 (dans les locaux de l\'IDRIS). La date limite d\'inscription est fix\xe9e au 4 mars.\\n\\nLes hackathons GPU permettent \xe0 des \xe9quipes de trois ou quatre d\xe9veloppeurs ou chercheurs d\'am\xe9liorer les performances de leurs codes HPC ou IA sous la houlette d\'un ou plusieurs mentors, experts en programmation GPU et issus des universit\xe9s, de laboratoires nationaux, de centres de calcul, d\'institutions gouvernementales et de constructeurs.\\n\\nIl n\'est pas n\xe9cessaire d\'\xeatre utilisateur de l\'IDRIS pour participer \xe0 cet \xe9v\xe9nement donc n\'h\xe9sitez pas \xe0 diffuser ce message aupr\xe8s de vos coll\xe8gues. Vous aurez \xe0 cette occasion acc\xe8s aux ressources de calcul de l\'IDRIS, afin de pouvoir tester votre code sur des GPU r\xe9cents allant jusqu\'aux NVIDIA H100.\\n\\nPour les projets HPC, il peut aussi bien s\'agir de commencer le portage d\'un code sur GPU en utilisant OpenACC, OpenMP, Kokkos, des biblioth\xe8ques GPU, CUDA, etc que d\'optimiser une impl\xe9mentation GPU existante. Dans le cas d\'un code de taille importante, il est recommand\xe9 de pr\xe9parer une mini-application repr\xe9sentative pour pouvoir \xeatre plus efficace pendant l\'\xe9v\xe9nement.\\n\\nPour les projets d\'IA, ce hackathon offre une occasion unique d\u2019explorer le finetuning, le d\xe9veloppement ou l\u2019\xe9valuation de mod\xe8les de pointe tels que les LLM et les applications GenAI. Vous pourrez optimiser vos mod\xe8les gr\xe2ce \xe0 des techniques avanc\xe9es comme la pr\xe9cision mixte, la parall\xe9lisation multi-GPU ou multi-n\u0153uds (DDP, PP, TP, CP), en utilisant des frameworks de base comme PyTorch ou TensorFlow, ou des outils sp\xe9cialis\xe9s tels que DeepSpeed, Megatron-LM, Nanotron ou encore NVIDIA NeMo. Bien qu\'un pr\xe9entra\xeenement complet soit hors de port\xe9e dans la dur\xe9e du hackathon, pr\xe9parer un code de pr\xe9entra\xeenement pour des mod\xe8les de grande \xe9chelle reste possible.\\n\\nL\'inscription se fait via la page de l\'\xe9v\xe8nement (en anglais) : https://www.openhackathons.org/s/siteevent/a0CUP00000sO9LV2A0/se000364.\\n\\n--------------------------------------------------------------------\\n\\nIDRIS is organizing a HPC and AI GPU Hackathon together with NVIDIA.\\n\\nThe Hackathon will be held on May 13th 2025 (remotely) and from May 20th through May 22nd (on site at IDRIS). The application deadline is March 4th 2025.\\n\\nGPU Hackathons provide opportunities for teams of three or four developers and researchers to accelerate their HPC or AI codes under the guidance of expert mentors from universities, national labs, computing centers, governmental institutions and hardware manufacturers in a collaborative environment.\\n\\nThe event is open to everyone even if you are not already a user of IDRIS computing resources so feel free to forward this message to your colleagues. During the Hackathon, you will be provided with access to the computing resources of IDRIS, in order to be able to benchmark your code on recent GPUs, including NVIDIA H100s.\\n\\nFor HPC projects, it could be the opportunity to start porting a code to GPU using OpenACC, OpenMP, Kokkos, GPU libraries, CUDA, etc or to optimize an existing GPU implementation. If your codebase is large in size, we recommend selecting and extracting a representative mini-app from the original application in order to be more efficient during the Hackathon.\\n\\nFor AI projects, it will be the occasion to explore finetuning, developing or evaluating cutting-edge models such as LLMs or GenAI applications. You will be able to improve your models thanks to advanced techniques like mixed precision, multi-GPU or multi-node parallelization (DDP, PP, TP, CP), by using standard frameworks such as PyTorch or TensorFlow, or specialized tools like DeepSpeed, Megatron-LM, Nanotron or NVIDIA NeMo. Even though a full pretraining cannot be achieved in the time frame of the Hackathon, you can get a pretraining code ready for large scale models.\\n\\nPlease register on https://www.openhackathons.org/s/siteevent/a0CUP00000sO9LV2A0/se000364."},{"id":"hackthon-idris-nvidia-2025","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/hackthon-idris-nvidia-2025","source":"@site/blog/2025/2025-01-09-hackathon-idris-nvidia-2025.md","title":"Hackathon GPU HPC et IA 2025 \xe0 l\'IDRIS","description":"Pour la cinqui\xe8me ann\xe9e cons\xe9cutive, l\'IDRIS organise, conjointement avec NVIDIA, un hackathon GPU HPC et IA.","date":"2025-01-09T00:00:00.000Z","tags":[{"inline":false,"label":"actu","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/actu","description":"Les actualit\xe9s diverses de l\'IDRIS."},{"inline":false,"label":"hackathon","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/hackathon","description":"Les hackathons organis\xe9s par l\'IDRIS."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"hackthon-idris-nvidia-2025","title":"Hackathon GPU HPC et IA 2025 \xe0 l\'IDRIS","authors":["idris"],"tags":["actu","hackathon"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02025-02","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-02"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02025-01","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-01"}},"content":"Pour la cinqui\xe8me ann\xe9e cons\xe9cutive, l\'IDRIS organise, conjointement avec NVIDIA, un hackathon GPU HPC et IA.\\n\\nIl aura lieu le **13 mai** (\xe0 distance) et les **20, 21 et 22 mai 2025** (dans les locaux de l\'IDRIS).\\n\\nLes hackathons GPU permettent \xe0 des \xe9quipes de trois ou quatre d\xe9veloppeurs ou chercheurs d\'am\xe9liorer les performances de leurs codes HPC ou IA sous la houlette d\'un ou plusieurs mentors, experts en programmation GPU et issus des universit\xe9s, de laboratoires nationaux, de centres de calcul, d\'institutions gouvernementales et de constructeurs.\\n\\nVous aurez \xe0 cette occasion acc\xe8s aux ressources de calcul de l\'IDRIS, afin de pouvoir tester votre code sur des GPU r\xe9cents allant jusqu\'aux NVIDIA H100.\\n\\nPour les projets HPC, il peut aussi bien s\'agir de commencer le portage d\'un code sur GPU en utilisant OpenACC, OpenMP, Kokkos, des biblioth\xe8ques GPU, CUDA, etc que d\'optimiser une impl\xe9mentation GPU existante. Dans le cas d\'un code de taille importante, il est recommand\xe9 de pr\xe9parer une mini-application repr\xe9sentative pour pouvoir \xeatre plus efficace pendant l\'\xe9v\xe9nement.\\n\\nPour les projets d\'IA, ce hackathon offre une occasion unique d\u2019explorer le finetuning, le d\xe9veloppement ou l\u2019\xe9valuation de mod\xe8les de pointe tels que les LLM et les applications GenAI. Vous pourrez optimiser vos mod\xe8les gr\xe2ce \xe0 des techniques avanc\xe9es comme la pr\xe9cision mixte, la parall\xe9lisation multi-GPU ou multi-n\u0153uds (DDP, PP, TP, CP), en utilisant des frameworks de base comme PyTorch ou TensorFlow, ou des outils sp\xe9cialis\xe9s tels que DeepSpeed, Megatron-LM, Nanotron ou encore NVIDIA NeMo. Bien qu\'un pr\xe9entra\xeenement complet soit hors de port\xe9e dans la dur\xe9e du hackathon, pr\xe9parer un code de pr\xe9entra\xeenement pour des mod\xe8les de grande \xe9chelle reste possible.\\n\\n**Merci de vous inscrire** sur https://www.openhackathons.org/s/siteevent/a0CUP00000sO9LV2A0/se000364.\\n\\n:::warning\\nLa date limite d\'\u200binscription est le 4 mars 2025.\\n:::"},{"id":"flash-info-2025-01","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-01","source":"@site/blog/2025/2025-01-08-flash-info-01.md","title":"Flash Info de l\'IDRIS n\xb02025-01","description":"Sommaire :","date":"2025-01-08T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2025-01","title":"Flash Info de l\'IDRIS n\xb02025-01","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Hackathon GPU HPC et IA 2025 \xe0 l\'IDRIS","permalink":"/documentation/idris-documentation-docusaurus/blog/hackthon-idris-nvidia-2025"},"nextItem":{"title":"D\xe9c\xe8s de Janine Connes","permalink":"/documentation/idris-documentation-docusaurus/blog/deces-janine-connes"}},"content":"Sommaire :\\n\\n* Meilleurs voeux !\\n* Prochaine r\xe9union du CU de l\'IDRIS : mercredi 22 janvier 2025\\n* Panoram\'IA : rendez-vous vendredi 24/01 \xe0 10h\\n* Formations IDRIS\\n\\n--------------------------------------------------------------------\\n\\n* Meilleurs voeux !\\n\\nL\'IDRIS souhaite une excellente ann\xe9e 2025 \xe0 toutes ses utilisatrices et tous ses utilisateurs !\\n\\n* Prochaine r\xe9union du CU de l\'IDRIS : mercredi 22 janvier 2025\\n\\nLa prochaine r\xe9union du Comit\xe9 des utilisateurs (CU) de l\'IDRIS aura lieu le mercredi 22 janvier 2025\\ndans les locaux de l\'IDRIS. N\'h\xe9sitez pas \xe0 transmettre vos demandes \xe0 l\'adresse : cu-elus at idris.fr.\\nPlus d\'information : http://www.idris.fr/cu.html\\n\\n* Panoram\'IA : rendez-vous vendredi 24/01 \xe0 10h\\n\\nL\'assistance de l\'IDRIS vous propose le vendredi matin 24/01 \xe0 10h, \\"Panoram\'IA\\" : le magazine vid\xe9o\\nmensuel et en direct qui aborde l\'actualit\xe9 scientifique et technique de l\'IA. Le direct ainsi que les\\nrediffusions sont disponibles sur notre cha\xeene Youtube \\"Un oeil sur l\'IDRIS\\" :\\nhttps://www.youtube.com/@idriscnrs.\\n\\n* Formations IDRIS\\n\\nPensez \xe0 vous inscrire d\xe8s maintenant aux formations IDRIS planifi\xe9es sur les prochains mois.\\n\\n\xc0 venir tr\xe8s prochainement :\\n\\n- Introduction Pratique au Deep Learning (IPDL), les 3 et 4 f\xe9vrier\\n- Architectures du Deep Learning (ArchDL), les 5 et 6 f\xe9vrier\\n\\nAutres formations programm\xe9es :\\n\\n- MPI, du 18 au 21 mars\\n- OpenMP, du 26 au 28 mars\\n- C++ Scientifique Moderne, du 9 au 11 avril\\n- Introduction \xe0 OpenACC et OpenMP GPU, du 16 au 18 avril\\n\\nPour plus d\'informations sur le catalogue des formations de l\'IDRIS et les modalit\xe9s d\'inscription :\\nhttp://www.idris.fr/formations/catalogue.html.\\n\\n--------------------------------------------------------------------"},{"id":"deces-janine-connes","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/deces-janine-connes","source":"@site/blog/2024/2024-11-28-deces-janine-connes.md","title":"D\xe9c\xe8s de Janine Connes","description":"Janine Connes, fondatrice du Centre inter-r\xe9gional de calcul \xe9lectronique (CIRC\xc9) du CNRS en 1969 et sa directrice jusqu\u2019en 1982, est d\xe9c\xe9d\xe9e le 28 novembre 2024 \xe0 l\u2019\xe2ge de 98 ans. Elle formait","date":"2024-11-28T00:00:00.000Z","tags":[{"inline":false,"label":"actu","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/actu","description":"Les actualit\xe9s diverses de l\'IDRIS."}],"hasTruncateMarker":true,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"deces-janine-connes","title":"D\xe9c\xe8s de Janine Connes","authors":["idris"],"tags":["actu"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02025-01","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2025-01"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-29","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-29"}},"content":"Janine Connes, fondatrice du Centre inter-r\xe9gional de calcul \xe9lectronique (CIRC\xc9) du CNRS en 1969 et sa directrice jusqu\u2019en 1982, est d\xe9c\xe9d\xe9e le 28 novembre 2024 \xe0 l\u2019\xe2ge de 98 ans. Elle formait\\navec son mari Pierre Connes un bin\xf4me scientifique de haut vol, Pierre \xe9tant l\u2019exp\xe9rimentateur et Janine traitant et analysant num\xe9riquement les r\xe9sultats. Ce duo a mis en place la m\xe9thode de\\nspectroscopie infrarouge par transform\xe9e de Fourier, d\'une importance majeure dans cette discipline. La [page](http://cwp.library.ucla.edu/Phase2/Connes,_Janine@841234567.html) du site de l\u2019University of California Los Angeles qui est consacr\xe9e \xe0 madame Connes en atteste. Elle a \xe9galement exerc\xe9 un r\xf4le crucial dans le d\xe9veloppement de la simulation num\xe9rique en France, permettant au CNRS de se doter des moyens n\xe9cessaires au service de toutes les communaut\xe9s scientifiques. Elle fait le r\xe9cit d\xe9taill\xe9 de cette \xe9pop\xe9e dans son livre [De l\'IBM 360/75 au superordinateur Jean Zay](https://laboutique.edpsciences.fr/produit/1253/9782759825783/de-l-ibm-360-75-au-superordinateur-jean-zay), \xe9crit avec la participation de Fran\xe7oise Perriquet et publi\xe9 en 2022[^1]. Nous n\u2019en rappellerons ici bri\xe8vement que les pr\xe9misses et les grandes \xe9tapes.\\n\\n\x3c!-- truncate --\x3e\\n\\nJanine Connes avait fait sa th\xe8se sous la direction de Pierre Jacquinot en 1954. Elle avait travaill\xe9 \xe0 d\xe9terminer la composition de l\u2019atmosph\xe8re de V\xe9nus et avait attir\xe9 l\u2019attention de Franck Gray, alors\\ndirecteur de la NASA qui recrutait l\u2019\xe9quipe de recherche pr\xe9alable \xe0 la premi\xe8re mission Viking, mission d\u2019exploration de Mars. Madame Connes acquit donc une grande exp\xe9rience en calculs lors de\\ns\xe9jours prolong\xe9s aux \xc9tats-Unis \xe0 partir de 1963, notamment au Jet Propulsion Laboratory (JPL) de la NASA. C\u2019est l\xe0 qu\u2019elle r\xe9alisa, encore et toujours main dans la main avec Pierre Connes, des\\navanc\xe9es importantes dans la spectroscopie infrarouge \xe0 transform\xe9e de Fourier[^2]. Elle put \xe9galement d\xe9couvrir le fonctionnement du centre de calcul de l\u2019universit\xe9 de Stanford et l\'activit\xe9 d\u2019autres centres\\nam\xe9ricains majeurs, notamment ceux d\u2019Argonne et du Lawrence Livermore National Laboratory. C\u2019est riche de toutes ses exp\xe9riences qu\u2019elle \xe9tait devenue sp\xe9cialiste de simulation num\xe9rique, \xe0 une\\n\xe9poque o\xf9 cette sp\xe9cialit\xe9 n\u2019en \xe9tait encore qu\u2019\xe0 ses balbutiements.\\n\\nPierre Jacquinot, lui-m\xeame physicien et pr\xe9c\xe9dent directeur du laboratoire Aim\xe9 Cotton alors install\xe9 \xe0 Meudon-Bellevue, \xe9tait alors confront\xe9 \xe0 la difficult\xe9 de disposer de la puissance de calcul\\nn\xe9cessaire \xe0 ses propres recherches. Devenu directeur g\xe9n\xe9ral du CNRS entre 1962 et 1969, il imposa l\u2019id\xe9e de cr\xe9er un centre de calcul d\xe9di\xe9 \xe0 tous les chercheurs ayant besoin de tr\xe8s grande puissance de\\ncalcul. Il voulait un centre g\xe9n\xe9raliste et d\xe9tach\xe9 de la recherche en informatique : \xab Donner aux utilisateurs de toute discipline la possibilit\xe9 de faire pour leur recherche les calculs dont ils ont besoin\\net qu\u2019ils ne peuvent pas faire ailleurs. \xbb\\n\\nEn 1968, c\u2019est donc vers Janine Connes qu\u2019il se tourna pour concevoir, mettre en place et diriger cette nouvelle structure d\u2019une nature alors unique en Europe. Forte de son exp\xe9rience outre-Atlantique,\\nelle put alors proposer \xe0 Pierre Jacquinot de b\xe2tir la nouvelle structure en question, en s\u2019inspirant tr\xe8s largement des mod\xe8les am\xe9ricains performants.\\n\\nNon sans avoir engendr\xe9 de vives turbulences, cela aboutit en 1969, sur le plateau du Moulon \xe0 Orsay, \xe0 la cr\xe9ation du Centre inter-r\xe9gional de calcul \xe9lectronique (CIRC\xc9), centre national de\\ncalcul du CNRS. Une partie des personnels venait de l\u2019Institut Blaise Pascal et l\u2019autre partie a \xe9t\xe9 recrut\xe9e sp\xe9cialement. Sa mission d\u2019unit\xe9 de services, \xe0 la disposition de toutes les disciplines\\nscientifiques, mais d\xe9tach\xe9e elle-m\xeame de la recherche en informatique, faisait du centre un lieu unique et essentiel pour toute la recherche scientifique fran\xe7aise.\\n\\nMadame Connes assura le d\xe9veloppement et la direction du CIRC\xc9 pendant 13 ans, jusqu\u2019en 1982, date \xe0 laquelle elle le quitta pour prendre la t\xeate de la toute nouvelle Direction de l\u2019informatique\\nscientifique du CNRS, cr\xe9\xe9e par le directeur g\xe9n\xe9ral d\u2019alors, Pierre Papon.\\n\\nPlus tard, en 1992, le directeur g\xe9n\xe9ral en poste, Fran\xe7ois Kourilsky, lan\xe7a le projet MIPS (Moyens informatiques performants pour la science), dans le but de pr\xe9parer la r\xe9organisation des\\ncentres de calcul du CNRS, CIRC\xc9 et part du CNRS dans le groupement d\u2019int\xe9r\xeat \xe9conomique du Centre de calcul vectoriel pour la recherche (CCVR), organisme qui eut, entre 1984 et 1993, un r\xf4le\\nprimordial pour l\u2019acc\xe8s et la promotion du calcul vectoriel dans la recherche. Le projet d\xe9boucha fin 1993 sur la cr\xe9ation du nouveau centre de calcul intensif du CNRS, l\u2019Institut du d\xe9veloppement et des ressources en informatique scientifique (IDRIS), dans les locaux de l\u2019ancien CIRC\xc9.\\n\\nL\u2019IDRIS, \xe0 son tour, a connu un d\xe9veloppement constant et spectaculaire. Il fait partie depuis 2007, avec ses partenaires du Tr\xe8s grand centre de calcul du CEA (TGCC), du Centre informatique\\nnational de l\u2019enseignement sup\xe9rieur (CINES) et sous l\u2019\xe9gide de la soci\xe9t\xe9 civile GENCI (Grand \xe9quipement national de calcul intensif), de l\u2019infrastructure nationale au service de l\u2019ensemble du\\nmonde de la recherche.\\n\\n\xc0 l\u2019heure de sa disparition, il convient de c\xe9l\xe9brer le r\xf4le pionnier, majeur et moteur qu\u2019a tenu\\nJanine Connes dans le d\xe9veloppement du calcul scientifique en France.\\n\\n[^1]: Janine Connes (avec la participation de Fran\xe7oise Perriquet), [De l\'IBM 360/75 au superordinateur Jean Zay](https://laboutique.edpsciences.fr/produit/1253/9782759825783/de-l-ibm-360-75-au-superordinateur-jean-zay), EDP Sciences, 2022.\\n[^2]: [Mary R. Masson](http://cwp.library.ucla.edu/Phase2/Connes,_Janine@841234567.html) : Fourier Transform Infrared Spectroscopy was \\"a very significant contribution to the theoretical and experimental development of Fourier Transform Infrared spectroscopy. Instrument developed were used for observation of the night sky. The advantage of such instruments in having an accurate laser-referenced frequency scale is referred to as the `Connes advantage.\'\\""},{"id":"flash-info-2024-29","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-29","source":"@site/blog/2024/2024-11-26-flash-info-29.md","title":"Flash Info de l\'IDRIS n\xb02024-29","description":"Adaptation aux nouveaux termes de la licence Anaconda","date":"2024-11-26T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-29","title":"Flash Info de l\'IDRIS n\xb02024-29","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"D\xe9c\xe8s de Janine Connes","permalink":"/documentation/idris-documentation-docusaurus/blog/deces-janine-connes"},"nextItem":{"title":"Restrictions de licence pour l\'utilisation d\'Alphafold3 sur Jean Zay","permalink":"/documentation/idris-documentation-docusaurus/blog/licence-alphafold3"}},"content":"Adaptation aux nouveaux termes de la licence Anaconda\\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nDepuis l\'\xe9t\xe9 2024, l\'utilisation des d\xe9p\xf4ts Anaconda est soumise \xe0 tarification \\n(https://legal.anaconda.com/policies/). Comme l\'IDRIS ne pr\xe9voit pas d\'acheter de licence, quelques \\nmesures ont \xe9t\xe9 mises en place sur Jean Zay pour limiter au maximum les requ\xeates vers les d\xe9p\xf4ts payants.\\n\\n1/ Les nouveaux environnements conda install\xe9s pour vous par l\'assistance IDRIS seront propos\xe9s via\\nMiniforge et non plus via Anaconda. Les anciens environnements bas\xe9s sur Anaconda resteront disponibles \\net pourront toujours \xeatre enrichis sur demande. L\'assistance prendra soin de viser des d\xe9p\xf4ts ouverts \\ncomme conda-forge.\\n\\n2/ Le comportement de tout environnement conda existant sur Jean Zay a \xe9t\xe9 modifi\xe9 gr\xe2ce au d\xe9ploiement\\nd\'un fichier de configuration /etc/conda/.condarc sur l\'ensemble des noeuds ayant un acc\xe8s \xe0 internet \\n(noeuds de connexion, prepost, compil, archive, visu). Gr\xe2ce \xe0 lui, toutes les installations effectu\xe9es \\npar conda visent maintenant en priorit\xe9 le d\xe9p\xf4t ouvert conda-forge.\\n\\n3/ Malgr\xe9 le d\xe9ploiement du nouveau fichier de configuration, certaines requ\xeates vers les d\xe9p\xf4ts \\nAnaconda peuvent persister si vous utilisez Anaconda ou Miniconda. Nous vous demandons d\'\xeatre attentives \\net attentifs lors de vos installations. Finalement, nous vous invitons fortement \xe0 travailler avec \\nMiniforge \xe0 partir de maintenant pour \xe9viter ce probl\xe8me. Un module \\"miniforge/24.9.0\\" est d\xe9j\xe0 \\ndisponible et de nouvelles versions seront r\xe9guli\xe8rement install\xe9es. Au contraire, nous ne pr\xe9voyons \\nplus de maintenir les modules Anaconda \xe0 l\'avenir.\\n\\nN\'h\xe9sitez pas \xe0 contacter assist@idris.fr si vous avez des questions \xe0 ce sujet.\\n\\nBien cordialement,\\nL\'\xe9quipe assistance IDRIS\\n\\n------------------------------------\\n\\nHello,\\n\\nSince summer 2024, the use of Anaconda repositories has been subject to pricing \\n(https://legal.anaconda.com/policies/). As IDRIS does not plan to purchase a license, a few measures \\nhave been put in place on Jean Zay to limit requests to paid repositories as much as possible.\\n\\n1/ The new conda environments installed for you by IDRIS support will be provided using Miniforge and \\nno longer using Anaconda. Older Anaconda-based environments will remain available and can still be \\ncompleted on request. Support will take care to target open repositories such as conda-forge.\\n\\n2/ The behavior of any existing conda environment on Jean Zay has been modified by deploying a \\nconfiguration file /etc/conda/.condarc on all nodes with internet access (connection nodes, prepost, \\ncompil, archive, visu). As a result, all installations performed by conda now target the open \\nrepository conda-forge as a priority.\\n\\n3/ Despite the deployment of the new configuration file, some requests to Anaconda repositories may \\npersist if you are using Anaconda or Miniconda. We ask you to be attentive during your installations. \\nFinally, we strongly advise you to work with Miniforge from now on to avoid this problem. A \\n\u201cminiforge/24.9.0\u201d module is already available, and new versions will be installed regularly. On the \\ncontrary, we no longer plan to maintain Anaconda modules in the future.\\n\\nPlease do not hesitate to contact assist@idris.fr if you have any question on this subject.\\n\\nBest regards,\\nThe IDRIS Support Team\\n\\n--------------------------------------------------------------------"},{"id":"licence-alphafold3","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/licence-alphafold3","source":"@site/blog/2024/2024-11-26-licence-alphafold3.md","title":"Restrictions de licence pour l\'utilisation d\'Alphafold3 sur Jean Zay","description":"Deepmind a ouvert le code d\'Alphafold 3 et l\'a rendu disponible sur Github. Cependant les poids du mod\xe8le sont eux soumis \xe0 une licence qui fait qu\'il ne sera pas possible de les rendre disponibles \xe0 tous les utilisateurs de l\'IDRIS.","date":"2024-11-26T00:00:00.000Z","tags":[{"inline":false,"label":"actu","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/actu","description":"Les actualit\xe9s diverses de l\'IDRIS."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"licence-alphafold3","title":"Restrictions de licence pour l\'utilisation d\'Alphafold3 sur Jean Zay","authors":["idris"],"tags":["actu"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-29","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-29"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-28","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-28"}},"content":"Deepmind a ouvert le code d\'Alphafold 3 et l\'a rendu disponible sur Github. Cependant les poids du mod\xe8le sont eux soumis \xe0 une licence qui fait qu\'il ne sera pas possible de les rendre disponibles \xe0 tous les utilisateurs de l\'IDRIS.\\n\\nhttps://github.com/google-deepmind/alphafold3/blob/main/WEIGHTS_TERMS_OF_USE.md\\n\\nEn effet, un certain nombre personnes utilisant les ressources de l\'IDRIS ne font pas partie du monde acad\xe9mique.\\n\\nNous allons contacter Deepmind pour voir s\'il est possible dans notre situation de partager les poids. En attendant une r\xe9ponse, nous allons appliquer la proc\xe9dure suivante :\\n\\n* L\'IDRIS fait l\'installation du code de fa\xe7on \xe0 ce qu\'il soit accessible \xe0 tous les utilisateurs.\\n* Chaque personne souhaitant utiliser Alphafold 3 devra obtenir l\'autorisation aupr\xe8s de Deepmind via le formulaire suivant https://forms.gle/svvpY4u2jsHEwWYS6 . Il est \xe0 noter que la r\xe9ponse peut prendre jusque 2 semaines.\\n* Les poids devront \xeatre install\xe9s localement sur le compte de chaque personne souhaitant utiliser Alphafold3.\\n\\nNous avons fait la demande des poids du mod\xe8le pour pouvoir faire des tests en interne.\\n\\nUne fois ces tests fait, nous publierons une documentation sur le site avec toutes les \xe9tapes pour faire fonctionner Alphafold 3."},{"id":"flash-info-2024-28","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-28","source":"@site/blog/2024/2024-11-14-flash-info-28.md","title":"Flash Info de l\'IDRIS n\xb02024-28","description":"Sommaire :","date":"2024-11-14T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-28","title":"Flash Info de l\'IDRIS n\xb02024-28","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Restrictions de licence pour l\'utilisation d\'Alphafold3 sur Jean Zay","permalink":"/documentation/idris-documentation-docusaurus/blog/licence-alphafold3"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-27","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-27"}},"content":"Sommaire :\\n\\n* Panoram\'IA : rendez-vous vendredi 15/11 \xe0 10h\\n* DSDIR non accessible depuis la partition H100\\n* Arr\xeat de l\'ancien espace STORE fin novembre 2024\\n* Formations IDRIS\\n\\n--------------------------------------------------------------------\\n\\n* Panoram\'IA : rendez-vous vendredi 15/11 \xe0 10h\\n\\nL\'assistance de l\'IDRIS vous propose ce vendredi matin 15/11 \xe0 10h, \\"Panoram\'IA\\" : le magazine vid\xe9o\\nmensuel et en direct qui aborde l\'actualit\xe9 scientifique et technique de l\'IA. Au programme de cette\\nsession : les br\xe8ves de l\'IA, une intervention d\'experts : \\"QROA : L\u2019art et la science de jailbreaker\\ndes LLMs\\" et notre s\xe9lection de papiers avec Papers Storm. Le direct ainsi que les rediffusions sont\\ndisponibles sur notre cha\xeene Youtube \\"Un oeil sur l\'IDRIS\\" : https://www.youtube.com/@idriscnrs.\\n\\n* DSDIR non accessible depuis la partition H100\\n\\nNous vous rappelons que l\'espace DSDIR sur lequel nous stockons les jeux de donn\xe9es et mod\xe8les publics\\nutiles \xe0 la communaut\xe9 (http://www.idris.fr/jean-zay/gpu/jean-zay-gpu-dataset.html) n\'est pour l\'instant\\npas accessible depuis la nouvelle partition H100 de Jean Zay. Du mat\xe9riel est actuellement en cours\\nd\'installation afin de permettre sa migration vers un nouveau syst\xe8me de stockage utilisant Lustre qui\\nsera accessible depuis toutes les partitions. Ce nouvel espace devrait \xeatre op\xe9rationnel d\'ici \xe0 la fin de\\nl\'ann\xe9e 2024. En attendant, si vous avez besoin d\'utiliser un jeu de donn\xe9es ou un mod\xe8le disponible dans\\nle DSDIR depuis un n\u0153ud H100, nous vous recommandons de le copier dans votre SCRATCH.\\n\\n* Arr\xeat de l\'ancien espace STORE fin novembre 2024\\n\\nSuite \xe0 la migration de l\'espace STORE vers un nouveau syst\xe8me de stockage Lustre durant l\'\xe9t\xe9, l\'ancien\\nespace STORE restait accessible en lecture seule en utilisant la variable d\'environnement \\"$OLDSTORE\\"\\n(http://www.idris.fr/jean-zay/modifications-extension-jean-zay-h100.html#cas_particulier_du_store).\\nL\'arr\xeat d\xe9finitif de cet espace aura lieu \xe0 la fin du mois de novembre 2024.\\n\\n* Formations IDRIS\\n\\nPensez \xe0 vous inscrire d\xe8s maintenant aux formations IDRIS planifi\xe9es pour le restant de l\'ann\xe9e et d\xe9but\\n2025 :\\n\\n- D\xe9bogage HPC, le 22 novembre\\n- Vectorisation SIMD, le 26 novembre\\n- Deep Learning Optimis\xe9 sur Jean Zay, les 14, 15, 16 et 17 janvier\\n- MPI, les 18, 19, 20 et 21 mars\\n- OpenMP, les 26, 27 et 28 mars\\n\\nPour plus d\'informations sur le catalogue des formations de l\'IDRIS et les modalit\xe9s d\'inscription :\\nhttp://www.idris.fr/formations/catalogue.html.\\n\\n--------------------------------------------------------------------"},{"id":"flash-info-2024-27","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-27","source":"@site/blog/2024/2024-10-01-flash-info-27.md","title":"Flash Info de l\'IDRIS n\xb02024-27","description":"Changements importants : QoS, JupyterHub, H100","date":"2024-10-01T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-27","title":"Flash Info de l\'IDRIS n\xb02024-27","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-28","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-28"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-26","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-26"}},"content":"Changements importants : QoS, JupyterHub, H100\\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nSuite \xe0 la maintenance d\'aujourd\'hui (mardi 1er octobre), plusieurs changements pourront vous impacter.\\n\\n* Changement de noms des QoS pour la partition A100\\n\\nAfin de pouvoir g\xe9rer plus finement le partage des ressources sur la machine, des QoS sp\xe9cifiques\\nont \xe9t\xe9 d\xe9finies pour la partition A100. Si vous utilisiez explicitement les QoS \\"qos_gpu-t3\\" ou\\n\\"qos_gpu-dev\\" dans vos soumissions de travaux ciblant cette partition, vous devrez utiliser \xe0 la\\nplace \\"qos_gpu_a100-t3\\" ou \\"qos_gpu_a100-dev\\". La QoS \\"qos_gpu_a100-t3\\" est utilis\xe9e par d\xe9faut\\net peut \xeatre omise.\\n\\nLes partitions CPU et V100 ne sont pas touch\xe9es par ce changement.\\n\\nLa documentation a \xe9t\xe9 mise \xe0 jour en cons\xe9quence : http://www.idris.fr/jean-zay/gpu/jean-zay-gpu-exec_partition_slurm.html#les_qos_disponibles.\\n\\n* Usage des QoS via JupyterHub\\n\\nSi vous souhaitez sp\xe9cifier une QoS lorsque vous utilisez le lanceur Slurm sur JupyterHub, il faudra\\nmaintenant la sp\xe9cifier manuellement dans le champ \\"Extra #SBATCH directives\\".\\n\\n* Changement de l\'adresse IP de JupyterHub\\n\\nL\'adresse IP de notre instance JupyterHub a \xe9t\xe9 modifi\xe9e. Il s\'agit maintenant de 130.84.132.56. Ce\\nchangement peut vous impacter si votre organisme applique un filtrage par adresse IP des connexions\\nsortantes. Si vous rencontrez des difficult\xe9s de connexion \xe0 JupyterHub, nous vous sugg\xe9rons de\\nprendre contact avec votre service informatique en leur signalement ce changement.\\n\\nPour rappel, la plage des adresses IP utilis\xe9es pour les machines et les services de l\'IDRIS est la\\nsuivante : 130.84.132.0/23. Nous recommandons d\'autoriser la plage compl\xe8te plut\xf4t que des adresses\\nIP sp\xe9cifiques afin de ne pas \xeatre affect\xe9 par de futurs changements internes \xe0 notre infrastructure.\\n\\n* Ouverture de la partition H100\\n\\nLes utilisateurs ayant d\xe9j\xe0 obtenu des heures H100 peuvent d\xe9sormais les utiliser. Vous pouvez\\nvous inspirer de l\'exemple ci-dessous :\\n\\n```sh\\n#!/bin/bash\\n#SBATCH --job-name=mon_travail       # nom du job\\n#SBATCH -A xyz@h100                  # comptabilite a utiliser, avec xyz le trigramme de votre projet\\n#SBATCH -C h100                      # pour cibler les noeuds H100\\n# Ici, reservation de 3x24=72 CPU (pour 3 taches) et de 3 GPU (1 GPU par tache) sur un seul noeud :\\n#SBATCH --nodes=1                    # nombre de noeud\\n#SBATCH --ntasks-per-node=3          # nombre de tache MPI par noeud (= ici nombre de GPU par noeud)\\n#SBATCH --gres=gpu:3                 # nombre de GPU par noeud (max 4 pour les noeuds H100)\\n# Sachant qu\'ici on ne reserve qu\'un seul GPU par tache (soit 1/4 des GPUs),\\n# l\'ideal est de reserver 1/4 des CPU du noeud pour chaque tache:\\n#SBATCH --cpus-per-task=24           # nombre de CPU par tache (1/4 des CPUs ici)\\n# /!\\\\ Attention, \\"multithread\\" fait reference a l\'hyperthreading dans la terminologie Slurm\\n#SBATCH --hint=nomultithread         # hyperthreading desactive\\n```\\n\\nNotez que les modules par d\xe9faut ne sont pas compatibles avec la partition H100. Afin de retrouver\\nl\'environnement logiciel sp\xe9cifique \xe0 cette partition, vous devez charger le module \\"arch/h100\\" :\\nhttp://www.idris.fr/jean-zay/cpu/jean-zay-cpu-doc_module.html#modules_compatibles_avec_la_partition_gpu_p6. Cela doit \xeatre fait dans vos scripts de soumission mais aussi dans votre terminal si vous avez\\nbesoin de compiler des codes.\\n\\nSi vous n\'avez pas encore d\'heures H100, le responsable du projet peut faire une demande\\nau fil de l\'eau sur le portail eDARI si n\xe9cessaire.\\n\\nN\'h\xe9sitez pas \xe0 contacter assist@idris.fr en cas de besoin.\\n\\nCordialement,\\nL\'\xe9quipe support de l\'IDRIS\\n\\n------------------------------------\\n\\nDear Jean Zay user,\\n\\nSeveral changes might affect you after today\'s maintenance operations (Tuesday October 1st):\\n\\n* Qos name changes for the A100 partition\\n\\nIn order to more precisely manage the ressource sharing of the machine, specific QoS have been defined\\nfor the A100 partition. If you used to explicitely specify \\"qos_gpu-t3\\" or \\"qos_gpu-dev\\" in your Slurm\\njobs targeting the A100 partition, you now have to use \\"qos_gpu_a100-t3\\" or \\"qos_gpu_a100-dev\\" instead.\\nNote that the \\"qos_gpu_a100-t3\\" QoS is used by default and may be omitted.\\n\\nThe CPU and V100 partitions are not affected by these changes.\\n\\nThe on-line documentation has been updated: http://www.idris.fr/eng/jean-zay/gpu/jean-zay-gpu-exec_partition_slurm-eng.html#available_qos\\n                                    \\n* Use of QoS through JupyterHub\\n\\nIf you wish to specify a QoS when using Slurm on JupyterHub, you now have to do it manually in\\nthe \\"Extra #SBATCH directives\\" field.\\n\\n* JupyterHub IP address change\\n\\nThe IP address of our JupyterHub instance has been modified. It is now 130.84.132.56. This change\\nmight impact you if your institution applies an IP address filtering of outgoing connections. If\\nyou run into difficulties when connectng to JupyterHub, we invite you to contact your local\\nadministrator to mention this change.\\n\\nAs a reminder, the set of IP addresses used for the IDRIS machines and services is the following:\\n130.84.132.0/23. We recommend to authorize the complete set rather than specific IP addresses so\\nas not to be affected by potential future internal changes of our infrastructure.\\n\\n* Opening of the H100 partition\\n\\nUsers who were already granted H100 computing hours may now use them. An example submission script is as follows:\\n\\n```sh\\n#!/bin/bash\\n#SBATCH --job-name=my_job            # job name\\n#SBATCH -A xyz@h100                  # account to use, with xyz the 3 letter code of your project\\n#SBATCH -C h100                      # to target H100 nodes\\n# Example reservation of 3x24=72 CPU (for 3 tasks) and 3 GPU (1 GPU per task) on one node:\\n#SBATCH --nodes=1                    # number of nodes\\n#SBATCH --ntasks-per-node=3          # number of MPI tasks per node (= number of GPU requested per node here)\\n#SBATCH --gres=gpu:3                 # number of GPU requested per node (max. 4 for H100 nodes)\\n# Since here only one GPU per task is requested (i.e., 1/4 of the available GPUs)\\n# the best way to proceed is to book 1/4 of the node\'s CPU for each task:\\n#SBATCH --cpus-per-task=24           # number of CPU per task (1/4 of the CPUs here)\\n# /!\\\\ Caution, \\"multithread\\" in Slurm vocabulary refers to hyperthreading.\\n#SBATCH --hint=nomultithread         # hyperthreading deactived\\n```\\n\\nNote that the default modules are not compatible with the H100 partition. In order to use the\\nsoftware environment dedicated to this partition, you need to load the \\"arch/h100\\" module:\\nhttp://www.idris.fr/eng/jean-zay/cpu/jean-zay-cpu-doc_module-eng.html#modules_compatible_with_gpu_p6_partition.\\nThis is needed for your submission scripts but also in your shell when compiling codes.\\n\\nIf you do not have H100 computing hours yet, your project manager may ask for supplementary hours\\n(\\"au fil de l\'eau\\") on the eDARI portal if necessary.\\n\\nDo not hesitate to contact assist@idris.fr if needed.\\n\\nBest regards,\\nThe IDRIS support team"},{"id":"flash-info-2024-26","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-26","source":"@site/blog/2024/2024-09-30-flash-info-26.md","title":"Flash Info de l\'IDRIS n\xb02024-26","description":"Arr\xeat \xe9lectrique : mardi 8 et mercredi 9 octobre 2024","date":"2024-09-30T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-26","title":"Flash Info de l\'IDRIS n\xb02024-26","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-27","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-27"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-25","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-25"}},"content":"Arr\xeat \xe9lectrique : mardi 8 et mercredi 9 octobre 2024\\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nUne maintenance de l\'infrastructure technique de l\'IDRIS n\xe9cessitera la mise \xe0 l\'arr\xeat du centre\\nmardi 8 et mercredi 9 octobre prochains. La machine Jean Zay sera indisponible du mardi 8 octobre\\n\xe0 6h jusqu\'au jeudi 10 octobre \xe0 12h. L\'espace STORE sera indisponible d\xe8s l\'apr\xe8s-midi du lundi\\n7 octobre.\\n\\nLe service de support aux utilisateurs sera ferm\xe9 pendant ces deux jours. Le site web restera\\naccessible et vous pourrez suivre la disponibilit\xe9 des machines sur la page habituelle :\\nhttp://www.idris.fr/statut.html.\\n\\nNous sommes d\xe9sol\xe9s pour la g\xeane que cette op\xe9ration pourrait occasionner.\\n\\nCordialement,\\nL\'\xe9quipe support de l\'IDRIS\\n\\n------------------------------------\\n\\nHello,\\n\\nA maintenance operation on the technical infrastructure of IDRIS will require the center to be\\nshut down completely on Tuesday October 8th and Wednesday October 9th. The Jean Zay machine will\\nbe unavailable from Tuesday October 8th at 6am until Thursday October 10th at noon. The STORE disk\\nspace will be unavailable starting from Monday October 7th in the afternoon.\\n\\nUser support will be closed for these two days. The website will remain accessible and you will\\nbe able to check the machine availability on the usual page: http://www.idris.fr/status.html.\\n\\nWe are sorry for any inconvenience this maintenance operation might cause.\\n\\nBest regards,\\nThe IDRIS User Support Team"},{"id":"flash-info-2024-25","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-25","source":"@site/blog/2024/2024-09-25-flash-info-25.md","title":"Flash Info de l\'IDRIS n\xb02024-25","description":"Sommaire :","date":"2024-09-25T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-25","title":"Flash Info de l\'IDRIS n\xb02024-25","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-26","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-26"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-24","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-24"}},"content":"Sommaire :\\n\\n* Panoram\'IA : rendez-vous vendredi 27/09 \xe0 10h\\n* Formations IDRIS\\n\\n--------------------------------------------------------------------\\n\\n* Panoram\'IA : rendez-vous vendredi 27/09 \xe0 10h\\n\\nL\'assistance de l\'IDRIS vous propose ce vendredi matin 27/09 \xe0 10h, \\"Panoram\'IA\\" : le magazine vid\xe9o\\nmensuel et en direct qui aborde l\'actualit\xe9 scientifique et technique de l\'IA. Au programme de cette\\nsession : les br\xe8ves de l\'IA, les TransformerEngine, l\'HyperCloning et notre s\xe9lection de papiers avec\\nPapers Storm. Le direct ainsi que les rediffusions sont disponibles sur notre cha\xeene Youtube \\"Un oeil\\nsur l\'IDRIS\\" : https://www.youtube.com/@idriscnrs. Les sessions suivantes auront lieu les 18 octobre \ud83c\udf83,\\n15 novembre et 6 d\xe9cembre \ud83c\udf85.\\n\\n* Formations IDRIS\\n\\nPensez \xe0 vous inscrire d\xe8s maintenant aux formations IDRIS planifi\xe9es pour le restant de l\'ann\xe9e :\\n\\n- OpenMP, du 16 au 18 octobre\\n- Introduction pratique au Deep Learning, les 4 et 5 novembre\\n- Architectures du Deep Learning, les 6 et 7 novembre\\n- Atelier de lancement en Deep Learning, le 8 novembre\\n- D\xe9bogage HPC, le 22 novembre\\n- Vectorisation SIMD, le 26 novembre\\n- Introduction \xe0 la biblioth\xe8que PETSc, les 5 et 6 d\xe9cembre\\n\\nPour plus d\'informations sur le catalogue 2024 des formations de l\'IDRIS et les modalit\xe9s d\'inscription :\\nhttp://www.idris.fr/formations/catalogue.html.\\n\\n--------------------------------------------------------------------"},{"id":"flash-info-2024-24","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-24","source":"@site/blog/2024/2024-09-24-flash-info-24.md","title":"Flash Info de l\'IDRIS n\xb02024-24","description":"Op\xe9ration sur le gestionnaire de travaux Slurm le 1er octobre","date":"2024-09-24T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-24","title":"Flash Info de l\'IDRIS n\xb02024-24","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-25","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-25"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-23","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-23"}},"content":"Op\xe9ration sur le gestionnaire de travaux Slurm le 1er octobre\\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nDans le cadre de l\'int\xe9gration de la nouvelle partition H100 \xe0 la machine Jean Zay, une op\xe9ration\\nest pr\xe9vue sur le gestionnaire de travaux Slurm le mardi 1er octobre 2024 de 8h \xe0 13h. La machine\\nsera indisponible pendant cette p\xe9riode.\\n\\nContrairement aux op\xe9rations de maintenance habituelles, les travaux en attente qui n\'auront pas\\npu s\'ex\xe9cuter avant la maintenance seront perdus. Il vous faudra les soumettre \xe0 nouveau au\\nred\xe9marrage de la machine.\\n\\nDe plus, la base de donn\xe9es contenant l\'historique des travaux Slurm sera r\xe9initialis\xe9e. Vous n\'aurez\\ndonc plus acc\xe8s aux informations concernant les travaux ant\xe9rieurs \xe0 la maintenance via la commande\\n\\"sacct\\". N\xe9anmoins cela n\'impactera pas la comptabilit\xe9 des heures consomm\xe9es visible via la commande\\n\\"idracct\\".\\n\\nNous sommes d\xe9sol\xe9s pour la g\xeane que cette op\xe9ration pourrait occasionner.\\n\\nCordialement,\\nL\'\xe9quipe support de l\'IDRIS\\n\\n------------------------------------\\n\\nHello,\\n\\nAs part of the integration of the new H100 partition to the Jean Zay machine, an operation is planned\\non the job scheduler Slurm on Tuesday, October 1st 2024 from 8am to 1pm. The machine will be unavailable\\nduring that time.\\n\\nUnlike the usual maintenance operations, the pending jobs that could not run before the maintenance\\noperation will be lost. You will have to resubmit them after the machine is back online.\\n\\nMoreover, the database which stores the Slurm jobs history will be reset. This means you will not have\\naccess anymore to the information about past jobs using the \\"sacct\\" command. However, there will be no\\nimpact on the accounting of your computing hours visible using the \\"idracct\\" command.\\n\\nWe are sorry for any inconvenience this maintenance operation might cause.\\n\\nBest regards,\\nThe IDRIS User Support Team"},{"id":"flash-info-2024-23","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-23","source":"@site/blog/2024/2024-09-09-flash-info-23.md","title":"Flash Info de l\'IDRIS n\xb02024-23","description":"Sommaire :","date":"2024-09-09T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-23","title":"Flash Info de l\'IDRIS n\xb02024-23","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-24","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-24"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-22","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-22"}},"content":"Sommaire :\\n\\n* Prochaine r\xe9union du CU de l\'IDRIS : jeudi 26 septembre 2024\\n* L\'IDRIS participe \xe0 la F\xeate de la Science les 11 et 12 octobre 2024\\n* Formations IDRIS\\n\\n------------------------------------------------------------------\\n\\n* Prochaine r\xe9union du CU de l\'IDRIS : jeudi 26 septembre 2024\\n\\nLa prochaine r\xe9union du Comit\xe9 des utilisateurs (CU) de l\'IDRIS aura lieu le 26 septembre 2024 dans les locaux de l\'IDRIS. N\'h\xe9sitez pas \xe0 transmettre vos demandes \xe0 l\'adresse : cu-elus at idris.fr. Plus d\'information : http://www.idris.fr/cu.html\\n\\n* L\'IDRIS participe \xe0 la F\xeate de la Science les 11 et 12 octobre 2024\\n\\nSuite au succ\xe8s rencontr\xe9 les ann\xe9es pr\xe9c\xe9dentes, l\'IDRIS renouvelle l\'exp\xe9rience et participe \xe0 nouveau aux Visites !nsolites du CNRS organis\xe9es dans le cadre de la F\xeate de la Science. Les inscriptions sont ouvertes du 2 au 22 septembre 2024 ! Pour plus d\'information : http://www.idris.fr/annonces/idris-fete-de-la-science.html.\\n\\n* Formations IDRIS\\n\\nPensez \xe0 vous inscrire d\xe8s maintenant aux formations IDRIS planifi\xe9es pour le restant de l\'ann\xe9e :\\n\\n- MPI, du 24 au 27 septembre\\n- Workshop Jean Zay, les 3 et 4 octobre\\n- OpenMP, du 16 au 18 octobre\\n- Deep Learning Optimis\xe9 sur Jean Zay, du 22 au 25 octobre\\n- Introduction pratique au Deep Learning, les 4 et 5 novembre\\n- Architectures du Deep Learning, les 6 et 7 novembre\\n- Atelier de lancement en Deep Learning, le 8 novembre\\n- D\xe9bogage HPC, le 22 novembre\\n- Vectorisation SIMD, le 26 novembre\\n- Introduction \xe0 OpenACC et OpenMP GPU, du 27 au 29 novembre\\n- Introduction \xe0 la biblioth\xe8que PETSc, les 5 et 6 d\xe9cembre\\n\\nPour plus d\'information sur le catalogue 2024 des formations de l\'IDRIS et les modalit\xe9s d\'inscription : http://www.idris.fr/formations/catalogue.html.\\n\\n------------------------------------------------------------------"},{"id":"flash-info-2024-22","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-22","source":"@site/blog/2024/2024-07-31-flash-info-22.md","title":"Flash Info de l\'IDRIS n\xb02024-22","description":"Arr\xeat du SCRATCH actuel le 3 septembre 2024","date":"2024-07-31T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-22","title":"Flash Info de l\'IDRIS n\xb02024-22","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-23","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-23"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-21","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-21"}},"content":"Arr\xeat du SCRATCH actuel le 3 septembre 2024\\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nDans le cadre du renouvellement des espaces de stockage accompagnant l\'extension H100 de Jean Zay,\\nl\'actuel espace SCRATCH sera d\xe9finitivement arr\xeat\xe9 le mardi 3 septembre 2024.\\n\\nComme annonc\xe9 pr\xe9c\xe9demment, *il n\'y aura pas de recopie automatique du contenu actuel du SCRATCH\\nvers le nouvel espace*.\\n\\nAfin d\'anticiper cet arr\xeat, nous vous invitons donc \xe0 recopier d\xe8s maintenant les donn\xe9es que vous\\nsouhaitez conserver vers le nouvel espace d\xe9j\xe0 accessible via la variable d\'environnement $NEWSCRATCH\\n(ou $ALL_CCFRNEWSCRATCH pour l\'espace commun au projet) et \xe0 l\'utiliser dans vos travaux en modifiant\\nvos scripts de soumission en cons\xe9quence.\\n\\nLes transferts peuvent \xeatre effectu\xe9s via un ou plusieurs travaux sur la partition \\"archive\\" ou en\\ninteractif depuis les frontales si le volume \xe0 transf\xe9rer est limit\xe9 :\\nhttp://www.idris.fr/jean-zay/modifications-extension-jean-zay-h100.html#recopies_scratch_et_all_scratch.\\n\\nAfin d\'\xe9viter les confusions entre les diff\xe9rents espaces et pour faciliter le suivi des migrations,\\nnous vous recommandons de supprimer les donn\xe9es dont vous n\'avez plus besoin et celles transf\xe9r\xe9es\\navec succ\xe8s.\\n\\nN\'oubliez pas que ce nouvel espace SCRATCH reste lui aussi soumis \xe0 la suppression automatique des\\ndonn\xe9es non utilis\xe9es pendant 30 jours.\\n\\nCordialement,\\nL\'\xe9quipe assistance de l\'IDRIS\\n\\n--------------------------------------------------\\n\\nDear Jean Zay user,\\n\\nAs part of the renewal of the storage spaces accompanying the H100 extension of Jean Zay, the current\\nSCRATCH disk space will be permanently shutdown on Tuesday, September 3rd, 2024.\\n\\nAs previously announced, *there will be no automatic copy of the current SCRATCH space to the new one*.\\n\\nTo anticipate this shutdown, we invite you to migrate as soon as possible the data you wish to keep to\\nthe new space already accessible through the $NEWSCRATCH (or $ALL_CCFRNEWSCRATCH for the common project\\nspaces) and to use that disk space in your jobs by modifying your submission scripts accordingly.\\n\\nThe data transfers can done using one or more jobs on the \\"archive\\" partition, or interactively from\\nthe login nodes if the volume to be transferred is limited:\\nhttp://www.idris.fr/eng/jean-zay/modifications-extension-jean-zay-h100-eng.html#scratch_et_all_scratch_copies.\\n\\nIn order to avoid confusions between the different disk spaces and facilitate the monitoring of the migration operation, we suggest that you remove any data that you will not need anymore or that you\\nhave already successfully migrated.\\n\\nPlease be aware that the new SCRATCH space is also subject to the 30 day deletion policy\\nof the unused data.\\n\\nBest regards,\\nThe IDRIS support team"},{"id":"flash-info-2024-21","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-21","source":"@site/blog/2024/2024-07-30-flash-info-21.md","title":"Flash Info de l\'IDRIS n\xb02024-21","description":"Migration du WORK et du HOME","date":"2024-07-30T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-21","title":"Flash Info de l\'IDRIS n\xb02024-21","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-22","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-22"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-20","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-20"}},"content":"Migration du WORK et du HOME\\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nComme annonc\xe9 pr\xe9c\xe9demment, l\'arriv\xe9e de l\'extension H100 s\'accompagne d\'un renouvellement des espaces\\nde stockage de Jean Zay avec l\'installation d\'un nouveau syst\xe8me de stockage Lustre qui offrira une\\nvolum\xe9trie de stockage plus importante et une bande passante am\xe9lior\xe9e.\\n\\nLa migration des HOME est termin\xe9e depuis la maintenance de ce matin (30 juillet 2024). Nous vous\\ninvitons \xe0 v\xe9rifier vos scripts pour corriger les \xe9ventuels chemins cod\xe9s en dur. Tout chemin de\\nla forme \\"/gpfs7kw/linkhome/...\\" doit devenir \\"/linkhome/...\\" ou, si possible, \xeatre remplac\xe9 par\\nl\'usage de la variable d\'environnement $HOME.\\n\\nLa migration des espaces WORK a d\xe9marr\xe9 aujourd\'hui. Elle est \xe9galement effectu\xe9e par les \xe9quipes\\nde l\'IDRIS, vous n\'avez donc pas d\'action particuli\xe8re \xe0 effectuer. Cette op\xe9ration se fera par lot\\npour \xe9viter une trop longue indisponibilit\xe9 de la machine. Elle n\xe9cessitera cependant l\'interruption\\ndes QoS \\"qos_cpu-t4\\" et \\"qos_gpu-t4\\" permettant l\'ex\xe9cution des travaux de plus de 20h.\\n\\nPour un projet donn\xe9, la migration se passera de la fa\xe7on suivante :\\n - 20h avant le d\xe9but de la migration, les travaux utilisant les heures du projet ne pourront plus\\n   d\xe9marrer afin d\'\xe9viter que des travaux essaient d\'acc\xe9der au WORK pendant l\'op\xe9ration (ils appara\xeetront\\n   alors avec le statut \\"AssocGrpJobsLimit\\")\\n - juste avant le d\xe9but de la migration, l\'espace WORK du projet deviendra compl\xe8tement indisponible,\\n   y compris depuis les frontales\\n - une fois la migration termin\xe9e, les variables d\'environnement seront modifi\xe9es afin de pointer\\n   vers les nouveaux espaces WORK sur le syst\xe8me de stockage Lustre et les travaux en attente pourront\\n   \xe0 nouveau s\'ex\xe9cuter.\\n\\nAttention : Si vous avez des travaux qui utilisent les heures d\'un projet mais acc\xe8dent \xe0 l\'espace\\nWORK d\'un autre projet, ils risquent d\'\xe9chouer car nous ne pourrons pas bloquer leur d\xe9marrage de\\nfa\xe7on pertinente.\\n\\nUne commande \\"idr_migstatus\\" vous permet de suivre la migration de vos projets en indiquant pour\\nchacun son statut actuel :\\n - \\"pending\\" : la migration n\'a pas encore \xe9t\xe9 effectu\xe9e, vos travaux peuvent toujours s\'ex\xe9cuter\\n   et vous avez acc\xe8s \xe0 votre WORK\\n - \\"planned\\" : la migration va commencer dans les prochaines 24h, les nouveaux travaux ne peuvent\\n   plus d\xe9marrer mais vous avez toujours acc\xe8s \xe0 votre WORK\\n - \\"in progress\\" : la migration est en cours, vous n\'avez plus acc\xe8s \xe0 votre WORK\\n - \\"migrated\\" : la migration est termin\xe9e, vous avez \xe0 nouveau acc\xe8s \xe0 votre WORK et vos travaux\\n   peuvent \xe0 nouveau s\'ex\xe9cuter.\\n\\nRemarque : Le chemin absolu des espaces WORK va changer \xe0 l\'occasion de la migration mais pour\\nsimplifier la transition, des liens seront mis en place de sorte \xe0 ce que les anciens chemins\\nabsolus restent fonctionnels au moins dans un premier temps. Une fois la migration effectu\xe9e,\\nnous vous invitons n\xe9anmoins \xe0 modifier les \xe9ventuels chemins de la forme \\"/gpfswork/...\\" ou\\n\\"/gpfsdswork/projects/...\\" qui pourraient appara\xeetre dans vos scripts (si possible en les\\nrempla\xe7ant par l\'usage de la variable d\'environnement) ou dans vos liens symboliques.\\n\\nNous nous excusons pour la g\xeane que ces op\xe9rations pourraient engendrer.\\n\\nCordialement,\\nL\'\xe9quipe support de l\'IDRIS\\n\\n--------------------------------------------------\\n\\nDear Jean Zay user,\\n\\nAs previously announced, the installation on the new H100 extension comes with a renewal of the Jean Zay\\nstorage spaces with the installation of a new Lustre storage system offering an increased storage capacity\\nand an improved bandwidth.\\n\\nThe migration of the HOME spaces is completed since today\'s maintenance operation (July 30th, 2024).\\nWe invite you to check your scripts in order to correct any hard-coded paths. Any path starting with\\n\\"/gpfs7kw/linkhome/...\\" should become \\"/linkhome/...\\" or, if possible, the $HOME environment variable\\nshould be used instead.\\n\\nThe migration of the WORK spaces started today. This operation is also handled by the IDRIS teams so you\\ndo not have any specific actions to perform. The migration will be done by batch of projects to avoid\\nhaving a long downtime of the machine. It will however require suspending the \\"qos_cpu-t4\\" and\\n\\"qos_gpu-t4\\" QoS which allow running jobs of more than 20h.\\n\\nFor a specific project, the migration process will be as follow:\\n - 20h before the migration begins, the jobs using computing hours allocated to that project will be\\n   held in queue (with the \\"AssocGrpJobsLimit\\" status) in order to avoid having jobs that use the WORK\\n   during the migration operation\\n - just before the migration starts, the WORK space will become completely unavailable, including from\\n   the login nodes\\n - once the migration is done, the environment variables will be modified to point to the new Lustre\\n   WORK space and your jobs will be able to run again.\\n\\nWarning: If you have jobs that use the computing hours from a project but access the WORK disk spaces\\nof another project, they might fail because we have no way to prevent them from starting when they\\nshould not.\\n\\nThe \\"idr_migstatus\\" command allows to monitor the migration of your projects by indicating the current\\nstatus of each of them:\\n - \\"pending\\" : the migration has not started yet, there is no impact on your jobs and you can access\\n   your WORK\\n - \\"planned\\" : the migration is going to start in the next 20h, jobs that are not yet running will\\n   stay pending but you can still access your WORK\\n - \\"in progress\\" : the migration is in progress, you will not have access to your WORK at this point\\n - \\"migrated\\" : the migration is done, you can access your WORK again and your jobs can run.\\n\\nNote: The absolute paths of the WORK spaces will be modified by the migration. However to ease the\\ntransition, symbolic links will be created in order to keep the old absolute paths working, at least\\nfor some times. Once the migration is completed, we do invite you to modify any absolute paths starting\\nwith \\"/gpfswork/...\\" or \\"/gpfsdswork/projects/...\\" that could appear in your scripts (use the environment\\nvariables whenever possible) or in your symbolic links.\\n\\nWe are sorry for the inconvenience those operations might cause.\\n\\nBest regards,\\nThe IDRIS support team"},{"id":"flash-info-2024-20","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-20","source":"@site/blog/2024/2024-07-24-flash-info-20.md","title":"Flash Info de l\'IDRIS n\xb02024-20","description":"Modalit\xe9s de migration du SCRATCH","date":"2024-07-24T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-20","title":"Flash Info de l\'IDRIS n\xb02024-20","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-21","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-21"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-19","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-19"}},"content":"Modalit\xe9s de migration du SCRATCH\\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nComme annonc\xe9 pr\xe9c\xe9demment, l\'arriv\xe9e de l\'extension H100 s\'accompagne d\'un renouvellement des espaces\\nde stockage de Jean Zay avec l\'installation d\'un nouveau syst\xe8me de stockage Lustre qui offrira une\\nvolum\xe9trie de stockage plus importante et une bande passante am\xe9lior\xe9e.\\n\\nAfin d\'anticiper l\'arr\xeat de l\'espace SCRATCH actuel, nous vous invitons \xe0 utiliser d\xe8s maintenant le\\nnouvel espace accessible via la variable d\'environnement $NEWSCRATCH (ou $ALL_CCFRNEWSCRATCH pour\\nl\'espace commun au projet) en modifiant vos scripts de soumission en cons\xe9quence. Une communication\\nult\xe9rieure vous pr\xe9cisera la date de cet arr\xeat avec au moins 15 jours de pr\xe9avis.\\n\\nIl n\'y aura pas de recopie automatique du contenu actuel du SCRATCH vers le nouvel espace. Par\\ncons\xe9quent, si vous souhaitez conserver certaines donn\xe9es actuellement stock\xe9es sur le SCRATCH,\\nveillez \xe0 les recopier vers votre nouvel espace NEWSCRATCH (par exemple via un ou plusieurs travaux\\nsur la partition \\"archive\\" ou en interactif depuis les frontales si le volume \xe0 transf\xe9rer est limit\xe9)\\net \xe0 supprimer les donn\xe9es dont vous n\'avez plus besoin.\\n\\nN\'oubliez pas que ce nouvel espace SCRATCH reste lui aussi soumis \xe0 la suppression automatique\\ndes donn\xe9es non utilis\xe9es pendant 30 jours.\\n\\nPour plus d\'informations sur les op\xe9rations en cours sur Jean Zay dans le cadre de l\'installation\\nde l\'extension H100 : http://www.idris.fr/jean-zay/modifications-extension-jean-zay-h100.html.\\n\\nCordialement,\\nL\'\xe9quipe assistance de l\'IDRIS\\n\\n--------------------------------------------------\\n\\nDear Jean Zay user,\\n\\nAs previously announced, the installation on the new H100 extension comes with a renewal of the Jean Zay\\nstorage spaces with the installation of a new Lustre storage system offering an increased storage\\ncapacity and an improved bandwidth.\\n\\nTo anticipate the shut down of the current SCRATCH space, we invite you as of now to start using the new\\nSCRATCH space already accessible through the $NEWSCRATCH (or $ALL_CCFRNEWSCRATCH for the common project\\nspaces) by modifying accordingly your submission scripts. The actual shut down date of the current SCRATCH\\nwill be announced later with at least a 15 day notice.\\n\\nThere will be no automatic copy of the current SCRATCH space to the new one. Therefore, if you wish to\\nkeep some data currently stored on the SCRATCH, be sure to copy it to your new space $NEWSCRATCH (for\\ninstance through one or more jobs on the \\"archive\\" partition, or interactively from the login nodes if\\nthe volume to be transferred is limited) and to remove data you do not need anymore.\\n\\nPlease be aware that the new SCRATCH space is also subject to the 30 day deletion policy\\nof the unused data.\\n\\nFor more information on the work in progress on Jean Zay for the H100 extension:\\nhttp://www.idris.fr/eng/jean-zay/modifications-extension-jean-zay-h100-eng.html.\\n\\nBest regards,\\nThe IDRIS support team"},{"id":"flash-info-2024-19","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-19","source":"@site/blog/2024/2024-07-23-flash-info-19.md","title":"Flash Info de l\'IDRIS n\xb02024-19","description":"Prolongation de l\'indisponibilit\xe9 du STORE","date":"2024-07-23T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-19","title":"Flash Info de l\'IDRIS n\xb02024-19","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-20","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-20"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-18","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-18"}},"content":"Prolongation de l\'indisponibilit\xe9 du STORE\\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nSuite \xe0 des difficult\xe9s techniques dans le cadre de la migration de l\'espace STORE (voir notre pr\xe9c\xe9dente\\ncommunication pour plus de d\xe9tails sur la migration : http://www.idris.fr/flash-info-idris/flash-info-de-l-idris-167.html),\\nl\'indisponibilit\xe9 de cet espace disque doit malheureusement \xeatre prolong\xe9e. L\'acc\xe8s au STORE devrait\\npouvoir \xeatre r\xe9tabli dans la journ\xe9e du jeudi 25 juillet. Nous vous invitons \xe0 consulter la page \\n\\"Disponibilit\xe9 des machines\\" de notre site (http://www.idris.fr/statut.html) ainsi que le mot du\\njour affich\xe9 \xe0 la connexion sur Jean Zay pour disposer des informations les plus \xe0 jour.\\n\\nPour rappel, il reste n\xe9anmoins possible d\'acc\xe9der en lecture seule \xe0 l\'ancien espace STORE en utilisant\\nla variable d\'environnement \\"$OLDSTORE\\".\\n\\nNous nous excusons pour la g\xeane occasionn\xe9e.\\n\\nCordialement,\\nL\'\xe9quipe support de l\'IDRIS\\n\\n--------------------------------------------------\\n\\nDear Jean Zay users,\\n\\nDue to technical difficulties encountered during the migration of the STORE space (cf. our last email\\nfor more details regarding the migration: http://www.idris.fr/flash-info-idris/flash-info-de-l-idris-167.html),\\nthis disk space will unfortunately be unavailable for a longer period than expected. Access to the\\nSTORE should be possible again by the end of Thursday July 25th. You can check the \\"Machine availability\\"\\nwebpage (http://www.idris.fr/status.html) and the message of the day displayed when logging in on\\nJean Zay for the latest updates.\\n\\nPlease note that it remains possible to have read-only access to the old STORE using the \\"$OLDSTORE\\"\\nenvironment variable.\\n\\nWe are sorry for the inconvenience this may cause.\\n\\nBest regards,\\nThe IDRIS support team"},{"id":"flash-info-2024-18","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-18","source":"@site/blog/2024/2024-07-16-flash-info-18.md","title":"Flash Info de l\'IDRIS n\xb02024-18","description":"Migration du STORE les 22 et 23 juillet","date":"2024-07-16T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-18","title":"Flash Info de l\'IDRIS n\xb02024-18","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-19","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-19"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-17","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-17"}},"content":"Migration du STORE les 22 et 23 juillet\\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nL\'espace disque STORE sera compl\xe8tement indisponible lundi 22 et mardi 23 juillet afin d\'en \\neffectuer la migration vers le nouveau syst\xe8me de stockage Lustre install\xe9 dans le cadre de \\nl\'extension H100 de Jean Zay et de l\'agrandissement de l\'espace WORK. Veillez donc bien \xe0 ne pas \\nsoumettre de travaux utilisant le STORE pendant cette p\xe9riode (les autres travaux pourront \\ncontinuer \xe0 s\'ex\xe9cuter normalement).\\n\\nComme annonc\xe9 le 18 juin, une modification des modalit\xe9s d\'acc\xe8s au STORE aura lieu \xe0 cette \\noccasion. Il ne sera plus possible d\'acc\xe9der \xe0 cet espace depuis les n\u0153uds de calcul. L\'acc\xe8s au \\nSTORE sera r\xe9tabli mardi 23 juillet en fin de journ\xe9e UNIQUEMENT sur les n\u0153uds de connexion et \\nsur les partitions \\"prepost\\", \\"visu\\", \\"compil\\" et \\"archive\\".\\n\\nJusqu\'\xe0 fin ao\xfbt, il restera possible d\'acc\xe9der en lecture seule \xe0 l\'ancien espace STORE en \\nutilisant la variable d\'environnement \\"$OLDSTORE\\". Cette modalit\xe9 d\'acc\xe8s sera \xe0 privil\xe9gier dans \\nles semaines qui suivront l\'op\xe9ration de migration. En effet, les donn\xe9es du nouveau STORE seront \\nalors uniquement disponibles sur bandes magn\xe9tiques ce qui pourra tr\xe8s fortement ralentir l\'acc\xe8s \\naux donn\xe9es (jusqu\'\xe0 plusieurs heures), le temps de repeupler le cache sur disques rotatifs avec \\nles donn\xe9es les plus r\xe9cemment utilis\xe9es. Notez que cette nouvelle variable d\'environnement est \\nd\xe9j\xe0 positionn\xe9e afin que vous puissiez anticiper la modification de vos scripts.\\n\\nPour rappel, le STORE est un espace d\xe9di\xe9 au stockage p\xe9renne et s\xe9curis\xe9 de donn\xe9es archiv\xe9es. \\nActuellement, il existe une redondance de l\'ensemble des donn\xe9es, stock\xe9es \xe0 la fois sur disques \\nrotatifs et sur bandes magn\xe9tiques. La pr\xe9sence de la donn\xe9e sur disques rotatifs permet une \\nlecture/\xe9criture relativement rapide de celle-ci. \xc0 l\'avenir, seules les donn\xe9es les plus r\xe9cemment \\nutilis\xe9es seront disponibles sur le cache sur disques rotatifs (toujours avec une copie de s\xe9curit\xe9 \\nsur bandes magn\xe9tiques).\\nLe reste des donn\xe9es sera uniquement stock\xe9 sur bandes magn\xe9tiques (avec deux copies sur des bandes\\ndiff\xe9rentes pour garantir la s\xe9curisation des donn\xe9es) avec des temps d\'acc\xe8s beaucoup plus longs,\\nincompatibles avec un usage direct depuis des calculs.\\n\\nNous vous invitons d\xe8s \xe0 pr\xe9sent \xe0 modifier vos scripts de soumission si vous acc\xe9dez directement \xe0\\nl\'espace STORE depuis les n\u0153uds de calcul. Pour vous guider, des exemples ont \xe9t\xe9 ajout\xe9s \xe0 la fin\\nde notre documentation sur les travaux multi-\xe9tapes : \\n     http://www.idris.fr/jean-zay/cpu/jean-zay-cpu-exec_cascade.html\\n\\nCordialement,\\nL\'\xe9quipe support de l\'IDRIS\\n\\n--------------------------------------------------\\n\\nDear Jean Zay users,\\n\\nThe STORE disk space will be totally unavailable on Monday July 22nd and Tuesday July 23rd in order \\nto migrate its data onto the new Lustre storage system installed in the framework of the Jean Zay H100\\nextension and the enlargement of the WORK disk space. Please make sure you do not submit any jobs using\\nthe STORE during this time (other jobs will continue to run normally).\\n\\nAs announced on June 18th, a change in the STORE access policy will take place after the migration, in\\nthat it won\'t be possible anymore to access this disk space from compute nodes. In turn, access to the\\nSTORE disk space will be again possible starting from Tuesday July 23rd evening, but only from login\\nnodes and from the \\"prepost\\", \\"visu\\", \\"compil\\" and \\"archive\\" partitions.\\n\\nUntil the end of August, it will remain possible to access the old STORE using the \\"$OLDSTORE\\" \\nenvironment variable. This way to access your archived data will be recommended in the weeks following \\nthe migration.\\nIndeed, the data on the new STORE will first be available only on magnetic tape (with long access times,\\npossibly up to several hours), while the rotating disk cache will be repopulated with the most recently\\nused data. Note that this new environment variable is already defined so that you can modify your scripts\\nin advance.\\n\\nAs a reminder, the STORE is a disk space dedicated to long term secured storage of archived data. In the\\ncurrent system, all the data is redundantly stored on rotating disks (\\"cache\\") and magnetic tapes, and\\nits availability on rotating disks enables a relatively fast read/write access time. In the future, only\\nthe most recently used data will be available on the rotating disk cache, with a security copy on the\\nmagnetic tapes. The remainder of the data will be stored only on magnetic tapes (with a double copy on\\ndifferent tapes to guarantee its security) with a much longer access time, incompatible with a direct\\nusage from compute nodes.\\n\\nWe invite you to change your submission scripts if you currently access the STORE space directly from\\nthe compute nodes. In order to help you, several examples have been added at the end of the multi-step\\njobs documentation:\\n     http://www.idris.fr/eng/jean-zay/cpu/jean-zay-cpu-exec_cascade-eng.html.\\n\\nBest regards,\\nThe IDRIS support team"},{"id":"flash-info-2024-17","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-17","source":"@site/blog/2024/2024-07-03-flash-info-17.md","title":"Flash Info de l\'IDRIS n\xb02024-17","description":"Sommaire :","date":"2024-07-03T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-17","title":"Flash Info de l\'IDRIS n\xb02024-17","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-18","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-18"},"nextItem":{"title":"Changements et impacts li\xe9s \xe0 l\'extension Jean Zay H100","permalink":"/documentation/idris-documentation-docusaurus/blog/impacts-extension-h100-jean-zay"}},"content":"Sommaire :\\n* Panoram\'IA : rendez-vous vendredi 5 juillet \xe0 10h\\n* Rappel : Modification des modalit\xe9s d\'acc\xe8s au STORE\\n* L\'IDRIS recrute dans le cadre des concours externes 2024\\n* Formations IDRIS\\n\\n* Panoram\'IA : rendez-vous vendredi 5 juillet \xe0 10h\\n\\nL\'assistance de l\'IDRIS vous propose vendredi matin 5 juillet \xe0 10h, \\"Panoram\'IA\\" : le magazine\\nvid\xe9o mensuel et en direct qui aborde l\'actualit\xe9 scientifique et technique de l\'IA. \\nAu programme de cette session : les br\xe8ves de l\'IA, extension H100 Jean Zay, retour d\'exp\xe9rience\\nsur CVPR2024 et notre s\xe9lection de papiers avec Papers Storm.\\nLe direct ainsi que les rediffusions sont disponibles sur notre cha\xeene Youtube \\"Un oeil sur l\'IDRIS\\" :\\nhttps://www.youtube.com/@idriscnrs.\\n\\n* Rappel : Modification des modalit\xe9s d\'acc\xe8s au STORE \\n\\nComme annonc\xe9 dans le Flash Info du 18 juin 2024, l\'acc\xe8s au STORE depuis les noeuds de calcul\\nne sera plus possible \xe0 partir du mardi 9 juillet 2024 :\\nhttp://www.idris.fr/flash-info-idris/flash-info-de-l-idris-165.html.\\n\\n* L\'IDRIS recrute dans le cadre des concours externes 2024\\n\\nDans le cadre des concours externes CNRS 2024, l\'IDRIS recrute :\\n  - Concours n\xb065 : 1 Expert-e calcul scientifique, fonction mutualis\xe9e Maison de la simulation (IR)\\n  - Concours n\xb067 : 1 Expert-e calcul scientifique (IR)\\n  - Concours n\xb0221 : 1 Gestionnaire d\u2019infrastructures (AI)\\n  - Concours n\xb0235 : 1 Assistant-e en gestion administrative (AI).\\n\\nPour plus d\'informations : http://www.idris.fr/annonces/idris-recrute.html.\\n\\n* Formations IDRIS\\n\\nPensez \xe0 vous inscrire d\xe8s maintenant aux formations IDRIS planifi\xe9es \xe0 la rentr\xe9e :\\n  - Programmation Hybride MPI/OpenMP, les 9 et 10 septembre\\n  - MPI, du 24 au 27 septembre\\n  - Workshop Jean Zay, les 3 et 4 octobre\\n  - OpenMP, du 16 au 18 octobre\\n  - Deep Learning Optimis\xe9 sur Jean Zay, du 22 au 25 octobre.\\n\\nPour plus d\'informations sur le catalogue 2024 des formations de l\'IDRIS\\net les modalit\xe9s d\'inscription : http://www.idris.fr/formations/catalogue.html.\\n\\n--------------------------------------------------------------------"},{"id":"impacts-extension-h100-jean-zay","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/impacts-extension-h100-jean-zay","source":"@site/blog/2024/2024-07-01-impacts-extension-h100-jean-zay.md","title":"Changements et impacts li\xe9s \xe0 l\'extension Jean Zay H100","description":"Ce post vous offre un aper\xe7u des op\xe9rations en cours dans le cadre de la mise en ordre de marche de l\'extension Jean Zay H100. Les informations donn\xe9es ici vont donc \xe9voluer au fil du temps et nous vous invitons \xe0 venir le consulter r\xe9guli\xe8rement.","date":"2024-07-01T00:00:00.000Z","tags":[{"inline":false,"label":"actu","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/actu","description":"Les actualit\xe9s diverses de l\'IDRIS."}],"hasTruncateMarker":true,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"impacts-extension-h100-jean-zay","title":"Changements et impacts li\xe9s \xe0 l\'extension Jean Zay H100","authors":["idris"],"tags":["actu"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-17","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-17"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-16","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-16"}},"content":"Ce post vous offre un aper\xe7u des op\xe9rations en cours dans le cadre de la mise en ordre de marche de l\'extension Jean Zay H100. Les informations donn\xe9es ici vont donc \xe9voluer au fil du temps et nous vous invitons \xe0 venir le consulter r\xe9guli\xe8rement.\\n\\n\x3c!-- truncate --\x3e\\n\\nL\'extension comporte de nouvelles frontales et des n\u0153uds de calcul ayant chacun :\\n\\n* 2 processeurs Intel Xeon Platinum 8468 (48 c\u0153urs \xe0 2,10 GHz), soit 96 CPU\\n* 4 GPU Nvidia H100 SXM5 80 Go\\n* 512 Go de m\xe9moire\\n\\nCette extension comporte \xe9galement de nouveaux espaces disques plus volumineux et plus rapides utilisant un syst\xe8me de fichier **Lustre**. Depuis la mi-ao\xfbt, ils remplacent les anciens espaces disques qui utilisaient un syst\xe8me de fichier **Spectrum Scale** d\'IBM. Les donn\xe9es enregistr\xe9es sur l\'ancien syst\xe8me de fichier (Spectrum Scale) ont \xe9t\xe9 copi\xe9es/d\xe9plac\xe9es sur le nouveau (Lustre) par l\'IDRIS, pour les espaces disques HOME, WORK, ALL_CCFRWORK, STORE et ALL_CCFRSTORE. Par contre, la recopie des espaces temporaires SCRATCH et ALL_CCFRSCRATCH \xe9taient de la responsabilit\xe9 de chaque utilisateur.\\n\\nNotez que la volum\xe9trie de stockage (en octets) des espaces WORK a \xe9t\xe9 augment\xe9e \xe0 cette occasion.\\n\\n## Changements importants depuis 1er octobre 2024\\n\\n### Changement des noms des QoS pour la partition A100\\n\\nAfin de pouvoir g\xe9rer plus finement le partage des ressources sur la machine, des QoS sp\xe9cifiques ont \xe9t\xe9 d\xe9finies pour la partition A100. Si vous utilisiez explicitement les QoS \u201cqos_gpu-t3\u201d ou \u201cqos_gpu-dev\u201d dans vos soumissions de travaux ciblant cette partition, vous devrez utiliser \xe0 la place \u201cqos_gpu_a100-t3\u201d ou \u201cqos_gpu_a100-dev\u201d. La QoS \u201cqos_gpu_a100-t3\u201d est utilis\xe9e par d\xe9faut et peut \xeatre omise.\\n\\nLes partitions CPU et V100 ne sont pas touch\xe9es par ce changement.\\n\\nLa documentation a \xe9t\xe9 mise \xe0 jour en cons\xe9quence : http://www.idris.fr/jean-zay/gpu/jean-zay-gpu-exec_partition_slurm.html#les_qos_disponibles.\\n\\n### Usage des QoS via JupyterHub\\n\\nSi vous souhaitez sp\xe9cifier une QoS lorsque vous utilisez le lanceur Slurm sur JupyterHub, il faudra maintenant la sp\xe9cifier manuellement dans le champ \u201cExtra #SBATCH directives\u201d.\\n\\n### Changement de l\'adresse IP de JupyterHub\\n\\nL\'adresse IP de notre instance JupyterHub a \xe9t\xe9 modifi\xe9e. Il s\'agit maintenant de 130.84.132.56. Ce changement peut vous impacter si votre organisme applique un filtrage par adresse IP des connexions sortantes. Si vous rencontrez des difficult\xe9s de connexion \xe0 JupyterHub, nous vous sugg\xe9rons de prendre contact avec votre service informatique en leur signalement ce changement.\\n\\nPour rappel, la plage des adresses IP utilis\xe9es pour les machines et les services de l\'IDRIS est la suivante : 130.84.132.0/23. Nous recommandons d\'autoriser la plage compl\xe8te plut\xf4t que des adresses IP sp\xe9cifiques afin de ne pas \xeatre affect\xe9 par de futurs changements internes \xe0 notre infrastructure.\\n\\n### Ouverture de la partition H100\\n\\nLes utilisateurs ayant d\xe9j\xe0 obtenu des heures H100 peuvent d\xe9sormais les utiliser. Vous pouvez vous inspirer de l\'exemple ci-dessous :\\n\\n```sh\\n#!/bin/bash\\n#SBATCH --job-name=mon_travail       # nom du job\\n#SBATCH -A xyz@h100                  # comptabilite a utiliser, avec xyz le trigramme de votre projet\\n#SBATCH -C h100                      # pour cibler les noeuds H100\\n# Ici, reservation de 3x24=72 CPU (pour 3 taches) et de 3 GPU (1 GPU par tache) sur un seul noeud :\\n#SBATCH --nodes=1                    # nombre de noeud\\n#SBATCH --ntasks-per-node=3          # nombre de tache MPI par noeud (= ici nombre de GPU par noeud)\\n#SBATCH --gres=gpu:3                 # nombre de GPU par noeud (max 4 pour les noeuds H100)\\n# Sachant qu\'ici on ne reserve qu\'un seul GPU par tache (soit 1/4 des GPUs),\\n# l\'ideal est de reserver 1/4 des CPU du noeud pour chaque tache:\\n#SBATCH --cpus-per-task=24           # nombre de CPU par tache (1/4 des CPUs ici)\\n# /!\\\\ Attention, \\"multithread\\" fait reference a l\'hyperthreading dans la terminologie Slurm\\n#SBATCH --hint=nomultithread         # hyperthreading desactive\\n```\\n\\n# Pour utiliser les modules compatibles avec cette partition H100\\n```sh\\nmodule purge\\nmodule load arch/h100\\n...\\n```\\n\\nNotez que les modules par d\xe9faut ne sont pas compatibles avec la partition H100. Afin de retrouver l\'environnement logiciel sp\xe9cifique \xe0 cette partition, vous devez charger le module \u201carch/h100\u201d : http://www.idris.fr/jean-zay/cpu/jean-zay-cpu-doc_module.html#modules_compatibles_avec_la_partition_gpu_p6. Cela doit \xeatre fait dans vos scripts de soumission mais aussi dans votre terminal si vous avez besoin de compiler des codes.\\n\\nSi vous n\'avez pas encore d\'heures H100, le responsable du projet peut faire une demande au fil de l\'eau sur le portail eDARI si n\xe9cessaire.\\n\\n## Modification des modalit\xe9s d\'acc\xe8s au STORE\\n\\nDepuis le lundi 22 juillet 2024, les modalit\xe9s d\'acc\xe8s au STORE ont \xe9t\xe9 modifi\xe9es. Ainsi, **l\'acc\xe8s au STORE en lecture et \xe9criture n\'est plus possible depuis les n\u0153uds de calcul** mais il reste possible depuis les n\u0153uds de connexion et les n\u0153uds des partitions \u201cprepost\u201d, \u201cvisu\u201d, \u201ccompil\u201d et \u201carchive\u201d. Nous vous invitons \xe0 modifier vos jobs si vous acc\xe9dez directement \xe0 l\'espace STORE depuis les n\u0153uds de calcul. Pour vous guider, des exemples ont \xe9t\xe9 ajout\xe9s \xe0 la fin de notre documentation sur les [travaux multi-\xe9tapes](http://www.idris.fr/jean-zay/cpu/jean-zay-cpu-exec_cascade.html#exemples_de_travaux_chaines_utilisant_le_store).\\n\\nCe changement est d\xfb au fait que la volum\xe9trie du cache du STORE (sur disques rotatifs) sera diminu\xe9e au profit de la volum\xe9trie du WORK. Nous ne pourrons plus garantir la redondance des donn\xe9es du STORE \xe0 la fois sur bandes magn\xe9tiques et sur disques rotatifs, comme c\'\xe9tait le cas jusqu\'\xe0 pr\xe9sent. La pr\xe9sence de la donn\xe9e sur disques rotatifs permet une lecture/\xe9criture relativement rapide de celle-ci. Avec la diminution de la volum\xe9trie du cache, dans certains cas, la donn\xe9e pourra n\'\xeatre stock\xe9e que sur bande magn\xe9tique (avec deux copies sur des bandes diff\xe9rentes pour garantir la redondance de donn\xe9e) ce qui d\xe9graderait fortement les temps d\'acc\xe8s \xe0 la donn\xe9e et par cons\xe9quent les performances de vos calculs en cas d\'acc\xe8s direct au STORE.\\n\\nPour rappel, le STORE est un espace d\xe9di\xe9 au stockage p\xe9renne de donn\xe9es archiv\xe9es.\\n\\n## Recopies HOME, WORK et STORE\\n\\nL\'IDRIS s\'est charg\xe9 de recopier les donn\xe9es stock\xe9es dans les HOME, WORK, ALL_CCFRWORK, STORE et ALL_CCFRSTORE.\\n\\n__ATTENTION__ : nous n\'avons fait que de simples copies ce qui peut entra\xeener des dysfonctionnements de vos ex\xe9cutions, notamment si vous utilisez des liens symboliques (comme ceux que nous recommandons de faire pour les [environnements Python personnels](http://www.idris.fr/jean-zay/gpu/jean-zay-gpu-python-env.html#conseils_generaux_avant_d_installer_localement_des_bibliotheques) par exemple). En effet, ceux-ci ne sont plus valides car les chemins des nouveaux r\xe9pertoires sont diff\xe9rents des anciens.\\n\\n### Cas particulier du HOME\\n\\nLa migration des HOME est termin\xe9e depuis la maintenance du 30 juillet 2024. Nous vous invitons \xe0 v\xe9rifier vos scripts pour corriger les \xe9ventuels chemins cod\xe9s en dur. Tout chemin de la forme `/gpfs7kw/linkhome/...` doit devenir `/linkhome/...` ou, si possible, \xeatre remplac\xe9 par l\'usage de la variable d\'environnement `$HOME`. Si vous utilisez des liens symboliques comme ceux que nous recommandons de faire pour les [environnements Python personnels](http://www.idris.fr/jean-zay/gpu/jean-zay-gpu-python-env.html#conseils_generaux_avant_d_installer_localement_des_bibliotheques), veuillez les refaire pour prendre en compte les nouveaux chemins d\'acc\xe8s aux nouveaux repertoires.\\n\\n### Cas particulier du WORK\\n\\nLa migration des espaces WORK est termin\xe9 depuis le 13 ao\xfbt 2024. Les QoS \u201cqos_cpu-t4\u201d et \u201cqos_gpu-t4\u201d permettant l\'ex\xe9cution des travaux de plus de 20h sont \xe0 nouveau fonctionnelles.\\n\\n**Remarque** : Le chemin absolu des espaces WORK a chang\xe9 \xe0 l\'occasion de la migration (voir la nouvelle valeur de la variable `$WORK`) mais pour simplifier la transition, des liens ont \xe9t\xe9 mis en place de sorte \xe0 ce que les anciens chemins absolus restent fonctionnels au moins dans un premier temps. Maintenant que la migration effectu\xe9e, nous vous invitons \xe0 modifier les \xe9ventuels chemins de la forme `/gpfswork/...` ou `/gpfsdswork/projects/...` qui pourraient appara\xeetre dans vos scripts (si possible en les rempla\xe7ant par l\'usage de la variable d\'environnement `$WORK`) ou dans vos liens symboliques pour ne plus utiliser les anciens repertoires.\\n\\n### Cas particulier du STORE\\n\\nConcernant le STORE, la migration a \xe9t\xe9 finalis\xe9e le 25 juillet 2024, la variable `$STORE` habituelle r\xe9f\xe9rence d\xe9sormais le nouveau syst\xe8me de fichier Lustre. Une variable `$OLDSTORE` a \xe9t\xe9 cr\xe9\xe9e pour r\xe9f\xe9rencer l\'espace sur l\'ancien syst\xe8me de fichier Spectrum Scale.\\n\\n```sh\\n# r\xe9f\xe9rence le STORE sur le filesystem Lustre\\n$ echo $STORE\\n/lustre/fsstor/projects/rech/...\\n\\n# r\xe9f\xe9rence l\'ancien STORE en lecture seule sur le filesystem Spectrum Scale\\n$ echo $OLDSTORE\\n/gpfsstore/rech/...\\n```\\n\\n__ATTENTION__ : **l\'acc\xe8s en lecture seule \xe0 l\'ancien espace STORE via la variable d\'environnement $OLDSTORE sera supprim\xe9 fin novembre 2024**. La variable `$OLDSTORE` ne sera alors plus d\xe9finie. Notez que, **l\'acc\xe8s au STORE en lecture et \xe9criture n\'est pas possible depuis les n\u0153uds de calcul** mais uniquement depuis les n\u0153uds de connexion et les n\u0153uds des partitions \u201cprepost\u201d, \u201cvisu\u201d, \u201ccompil\u201d et \u201carchive\u201d. Nous vous invitons \xe0 modifier vos jobs si vous acc\xe9dez directement \xe0 l\'espace OLDSTORE depuis les n\u0153uds de calcul. Pour vous guider, des exemples d\'encha\xeenements de jobs ont \xe9t\xe9 ajout\xe9s \xe0 la fin de notre documentation sur les [travaux multi-\xe9tapes](http://www.idris.fr/jean-zay/cpu/jean-zay-cpu-exec_cascade.html#exemples_de_travaux_chaines_utilisant_le_store).\\n\\n## SCRATCH et ALL_CCFRSCRATCH\\n\\n**Depuis le mardi 3 septembre 2024, la variable d\'environnement SCRATCH (et ses variantes comme ALL_CCFRSCRATCH) pointe vers le nouvel espace SCRATCH Lustre**. L\'ancien espace SCRATCH Spectrum Scale n\'est plus accessible.\\n\\nLa variable d\'environnement NEWSCRATCH (et ses variantes comme ALL_CCFRNEWSCRATCH) dispara\xeetra \xe0 terme et nous vous encourageons donc \xe0 la remplacer par SCRATCH d\xe8s maintenant.\\n\\n```sh\\n# r\xe9f\xe9rence le nouveau SCRATCH sur le filesystem Lustre\\n$ echo $SCRATCH\\n/lustre/fsn1/projects/rech/...\\n```\\n\\n## Changement des liens symboliques\\n\\nAttention, si vous avez dans votre r\xe9pertoire HOME des r\xe9pertoires tel que $HOME/.local, $HOME/.conda pointant via des liens symboliques vers l\'ancien WORK de la forme `/gpfswork/...`, il faut changer ces liens vers le nouveau WORK de la forme `/lustre/fswork/...`.\\n\\n```sh\\n$ cd $HOME\\n# Ici .local est un lien sur l\'ancien WORK\\n$ ls -al .local\\n ...  .local -> /gpfswork/...\\n# Supprime le lien\\n$ unlink .local\\n# Recree le lien avec la variable $WORK qui reference le nouveau WORK\\n$ ln -s $WORK/.local $HOME\\n# Lien sur le nouveau WORK\\n$ ls -al .local\\n ...  .local -> /lustre/fswork/...\\n ```"},{"id":"flash-info-2024-16","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-16","source":"@site/blog/2024/2024-06-18-flash-info-16.md","title":"Flash Info de l\'IDRIS n\xb02024-16","description":"Modification des modalit\xe9s d\'acc\xe8s au STORE","date":"2024-06-18T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-16","title":"Flash Info de l\'IDRIS n\xb02024-16","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Changements et impacts li\xe9s \xe0 l\'extension Jean Zay H100","permalink":"/documentation/idris-documentation-docusaurus/blog/impacts-extension-h100-jean-zay"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-15","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-15"}},"content":"Modification des modalit\xe9s d\'acc\xe8s au STORE \\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nAvec l\'arriv\xe9e de l\'extension H100 est \xe9galement pr\xe9vu un renouvellement des espaces de stockage\\ndurant l\'\xe9t\xe9. La volum\xe9trie de stockage (en octets) des espaces WORK sera augment\xe9e \xe0 cette \\noccasion. En contrepartie, les modalit\xe9s d\'acc\xe8s au STORE devront \xeatre adapt\xe9es. En particulier, \\nl\'acc\xe8s au STORE en lecture et \xe9criture ne sera plus possible depuis les n\u0153uds de calcul. Il \\nsera maintenu sur les noeuds de connexion et sur les partitions \\"prepost\\", \\"visu\\", \\"compil\\" et \\n\\"archive\\".\\n\\nCe changement sera effectif apr\xe8s la maintenance pr\xe9vue le mardi 9 juillet 2024. Nous vous \\ninvitons d\xe8s \xe0 pr\xe9sent \xe0 modifier vos jobs si vous acc\xe9dez directement \xe0 l\'espace STORE depuis \\nles n\u0153uds de calcul. Pour vous guider, des exemples ont \xe9t\xe9 ajout\xe9s \xe0 la fin de notre \\ndocumentation sur les travaux multi-\xe9tapes :\\n    http://www.idris.fr/jean-zay/cpu/jean-zay-cpu-exec_cascade.html\\n\\nPour rappel, le STORE est un espace d\xe9di\xe9 au stockage p\xe9renne de donn\xe9es archiv\xe9es. Actuellement,\\nil existe pour le STORE une redondance de la donn\xe9e, sauvegard\xe9e \xe0 la fois sur disques rotatifs \\net sur bandes magn\xe9tiques. La pr\xe9sence de la donn\xe9e sur disques rotatifs permet une \\nlecture/\xe9criture relativement rapide de celle-ci. \xc0 l\'avenir, la donn\xe9e pourra \xeatre stock\xe9e \\nuniquement sur bande magn\xe9tique (avec deux copies sur des bandes diff\xe9rentes pour garantir la \\nredondance de donn\xe9e) ce qui d\xe9graderait fortement les performances de vos calculs en cas \\nd\'acc\xe8s direct au STORE.\\n\\nN\'h\xe9sitez pas \xe0 contacter l\'assistance IDRIS (assist@idris.fr) si vous avez besoin d\'aide.\\n\\nBien cordialement,\\n\\nL\'\xe9quipe assistance de l\'IDRIS \\n\\n--------------------------------------------------\\n\\nHello,\\n\\nwith the arrival of the H100 extension, we are also planning to renew the storage spaces over the\\nsummer. The storage size (in bytes) of WORK spaces will be increased on this occasion. In return, \\naccess to the STORE will have to be adapted. In particular, read and write access to the STORE \\nwill no longer be possible from the compute nodes. It will be maintained on the login nodes and \\non the \\"prepost\\", \\"visu\\", \\"compil\\" and \\"archive\\" partitions.\\n\\nThis change will take effect after the maintenance scheduled for Tuesday, July 9, 2024. We invite \\nyou to modify your jobs now if you access the STORE space directly from the compute nodes. To \\nguide you, examples have been added at the end of our documentation on multi-step jobs:\\n    http://www.idris.fr/eng/jean-zay/cpu/jean-zay-cpu-exec_cascade-eng.html\\n\\nAs a reminder, the STORE is a space dedicated to the long-term storage of archived data. For now, \\nthe STORE provides redundant data storage on both rotating disks and magnetic tapes. The presence \\nof data on rotating disks means that it can be read and written relatively quickly. In the future, \\ndata may only be stored on magnetic tape (with two copies on different tapes to maintain data \\nredundancy), which would severely degrade the performance of your calculations when accessing the \\nSTORE directly.\\n\\nPlease do not hesitate to contact IDRIS support (assist@idris.fr) if you need any assistance.\\n\\nBest regards,\\n\\nThe IDRIS support team"},{"id":"flash-info-2024-15","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-15","source":"@site/blog/2024/2024-06-17-flash-info-15.md","title":"Flash Info de l\'IDRIS n\xb02024-15","description":"Correctif : Arr\xeat du 19 juin 8h au 21 juin midi et retour en Red Hat 8.6","date":"2024-06-17T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-15","title":"Flash Info de l\'IDRIS n\xb02024-15","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-16","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-16"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-14","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-14"}},"content":"Correctif : Arr\xeat du 19 juin 8h au 21 juin midi et retour en Red Hat 8.6\\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nContrairement \xe0 ce que nous avions annonc\xe9 vendredi, des contraintes techniques suppl\xe9mentaires nous\\nemp\xeachent finalement de maintenir l\'acc\xe8s \xe0 la partition A100 pendant l\'arr\xeat de la machine pr\xe9vu du\\nmercredi 19 juin 8h au vendredi 21 juin midi.\\n\\nLes frontales, les n\u0153uds de pr\xe9/post-traitement et compilation ainsi que les espaces de stockage resteront\\naccessibles du mercredi 19 juin vers 12h au vendredi 21 juin 8h.\\n\\nPar ailleurs le retour en arri\xe8re vers la version 8.6 du syst\xe8me d\'exploitation Red Hat de Jean Zay\\nne sera peut-\xeatre pas n\xe9cessaire et ne sera en tout cas pas r\xe9alis\xe9 \xe0 l\'occasion de cet arr\xeat.\\n\\nNous nous excusons pour la g\xeane occasionn\xe9e.\\n\\nBien cordialement,\\nL\'\xe9quipe assistance de l\'IDRIS\\n\\n--------------------------------------------------\\n\\nHello,\\n\\nContrary to what we announced on Friday, extra technical constraints finally prevent us from maintaining\\naccess to the A100 partition during the machine shutdown scheduled from Wednesday, June 19 8am to Friday,\\nJune 21 at noon.\\n\\nFront nodes, pre/post and compilation nodes, as well as storage spaces will remain accessible from\\nWednesday around noon to Friday 8 am.\\n\\nBesides, the roll-back to the 8.6 version of the Red Hat Jean Zay operating system might not be necessary\\nand will, in any case, not be performed during this shutdown.\\n\\nWe apologize for the inconvenience.\\n\\nBest regards,\\nThe IDRIS user support team"},{"id":"flash-info-2024-14","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-14","source":"@site/blog/2024/2024-06-14-flash-info-14.md","title":"Flash Info de l\'IDRIS n\xb02024-14","description":"Arr\xeat du 19 juin 8h au 21 juin midi et retour en Red Hat 8.6","date":"2024-06-14T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-14","title":"Flash Info de l\'IDRIS n\xb02024-14","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-15","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-15"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-13","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-13"}},"content":"Arr\xeat du 19 juin 8h au 21 juin midi et retour en Red Hat 8.6 \\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nDans le cadre de l\'installation de l\'extension H100 de Jean Zay, un arr\xeat de la machine est n\xe9cessaire\\ndu mercredi 19 juin 8h au vendredi 21 juin midi afin d\'effectuer des op\xe9rations sur l\'infrastructure\\nde l\'IDRIS.\\n\\nLes frontales, les n\u0153uds A100 et de pr\xe9/post-traitement ainsi que les espaces de stockage resteront\\naccessibles du mercredi 19 juin vers 14h au vendredi 21 juin 8h. Seuls les travaux dont la dur\xe9e\\nmaximale est suffisamment courte pourront s\'ex\xe9cuter pendant cette p\xe9riode.\\n\\nA l\'occasion de cet arr\xeat, nous effectuerons par ailleurs un retour en arri\xe8re vers la version 8.6\\ndu syst\xe8me d\'exploitation Red Hat de Jean Zay. Cela fait suite \xe0 des probl\xe8mes de stabilit\xe9 observ\xe9s\\nsur l\'acc\xe8s aux syst\xe8mes de fichiers depuis la mise \xe0 jour vers Red Hat 9.2. Ce retour en arri\xe8re\\nsera effectif d\xe8s mercredi apr\xe8s-midi.\\n\\nCe changement de version du syst\xe8me d\'exploitation devrait normalement avoir un impact limit\xe9 sur\\nvotre utilisation de la machine. Nous vous recommandons n\xe9anmoins de recompiler vos codes une fois\\nla mise \xe0 jour effectu\xe9e, m\xeame si la majorit\xe9 devrait continuer \xe0 fonctionner sans action de votre part.\\n\\nNous nous excusons pour la g\xeane occasionn\xe9e par ces op\xe9rations. En cas de probl\xe8me, n\'h\xe9sitez pas\\n\xe0 contacter l\'assistance de l\'IDRIS.\\n\\nBien cordialement,\\nL\'\xe9quipe assistance de l\'IDRIS\\n\\n--------------------------------------------------\\n\\nHello,\\n\\nJean Zay will be unavailable from Wednesday, June 19th at 8am to Friday, June 21st at noon in order to\\nperform some operations on the infrastructure of IDRIS required to finalize the installation of the\\nH100 extension of Jean Zay. \\n\\nThe login nodes, A100 nodes, pre/post-processing nodes and storage spaces will nevertheless be usable\\nfrom Wednesday, June 19th around 2pm to Friday, June 21st at 8am. The jobs targeting those nodes will\\nbe executed as long as their maximum elapsed time is short enough.\\n\\nAdditionally, during that downtime, the operating system of the Jean Zay supercomputer will be downgraded\\nto Red Hat 8.6 due to some stability issues affecting the accesses to the filesystems since the upgrade\\nto Red Hat 9.2. This downgrade will take effect on Wednesday afternoon.\\n\\nThis operating system version change should have a limited impact on your use of the machine.\\nNevertheless, we recommend that you recompile your codes once after the update, even if the\\nmajority of them should continue to work without any action on your part.\\n\\nWe are sorry for the inconvenience caused by those operations. In case of problems, contact the\\nIDRIS Support.\\n\\nBest regards,\\nThe IDRIS user support team"},{"id":"flash-info-2024-13","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-13","source":"@site/blog/2024/2024-06-04-flash-info-13.md","title":"Flash Info de l\'IDRIS n\xb02024-13","description":"Migration du syst\xe8me d\'exploitation en Red Hat 9.2","date":"2024-06-04T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-13","title":"Flash Info de l\'IDRIS n\xb02024-13","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-14","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-14"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-12","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-12"}},"content":"Migration du syst\xe8me d\'exploitation en Red Hat 9.2\\n\\n\\n[English version below]\\n\\nBonjour,\\n\\n\xc0 l\'occasion de la maintenance d\'aujourd\'hui (4 juin 2024), le syst\xe8me d\'exploitation du supercalculateur\\nJean Zay est mis \xe0 jour en Red Hat 9.2 (contre 8.6 actuellement). Cette mise \xe0 jour a pour but de disposer\\nd\'un environnement logiciel r\xe9cent sur Jean Zay et s\'inscrit dans le cadre de la pr\xe9paration de\\nl\'installation de l\'extension H100 de Jean Zay.\\n\\nCe changement de version du syst\xe8me d\'exploitation devrait normalement avoir un impact limit\xe9 sur votre\\nutilisation de la machine. Nous vous recommandons n\xe9anmoins de recompiler vos codes une fois la mise \xe0\\njour effectu\xe9e, m\xeame si la majorit\xe9 devrait continuer \xe0 fonctionner sans action de votre part.\\n\\nNous vous signalons n\xe9anmoins quelques points d\'attention :\\n\\n- Les compilateurs GNU distribu\xe9s avec le syst\xe8me passent en version 11.3.1 \xe0 l\'occasion de cette mise\\n  \xe0 jour. Les compilateurs Intel dont la version est inf\xe9rieure \xe0 2021 ne sont plus compatibles avec\\n  cette version du compilateur GNU. Les modules \\"intel-compilers\\" inf\xe9rieurs \xe0 2021 chargent donc\\n  maintenant automatiquement les compilateurs GNU 8.5.0. Il reste possible d\'utiliser une autre version\\n  (inf\xe9rieure \xe0 11) en la chargeant avant le compilateur Intel, par exemple \\"module load gcc/10.1.0 intel-compilers/19.1.3\\".\\n\\n- Le retour en production de JupyterHub sera d\xe9cal\xe9 de quelques heures, l\'acc\xe8s devrait \xeatre \xe0 nouveau\\n  possible d\'ici la fin de la journ\xe9e.\\n\\n- L\'acc\xe8s aux noeuds de visualisation via un client VNC sera suspendu quelques jours le temps de\\n  finaliser la migration.\\n\\n- En raison de l\'obsolescence de certains algorithmes de chiffrement, l\'acc\xe8s \xe0 Jean Zay depuis\\n  certaines machines utilisant une version ancienne de SSH pourrait ne plus \xeatre possible (tout\\n  comme l\'acc\xe8s depuis Jean Zay \xe0 de telles machines).\\n\\nEn cas de probl\xe8me, n\'h\xe9sitez pas \xe0 contacter l\'assistance de l\'IDRIS.\\n\\nBien cordialement,\\nL\'\xe9quipe assistance de l\'IDRIS\\n\\n--------------------------------------------------\\n\\nHello,\\n\\nDuring today\'s maintenance (June 4th, 2024), the operating system of the Jean Zay supercomputer has\\nbeen updated to Red Hat 9.2 (from 8.6 currently). This update aims at making a recent software\\nenvironment available on Jean Zay and is part of the preparation framework for the installation\\nof the Jean Zay H100 extension.\\n\\nThis operating system version change should have a limited impact on your use of the machine.\\nNevertheless, we recommend that you recompile your codes once after the update, even if the\\nmajority of them should continue to work without any action on your part.\\n\\nPlease note:\\n\\n- The GNU compilers bundled with the operating system have been updated to version 11.3.1.\\n  The Intel compilers whose version is lower than 2021 are not compatible anymore with this\\n  version of the GNU compilers. The \\"intel-compilers\\" modules lower than 2021 will now automatically\\n  load the GNU compilers 8.5.0. You can still use another version (lower than 11) by loading\\n  it before the Intel compiler, for example \\"module load gcc/10.1.0 intel-compilers/19.1.3\\".\\n\\n- JupyterHub will still be unavailable for a few hours, it should be back online by the end of the day.\\n\\n- The access to the visualization node through a VNC client will be suspended for a few days\\n  while we finalize the migration.\\n\\n- Due to the deprecation of some encryption algorithms, the access to Jean Zay from some machines\\n  using an old SSH version might not be possible anymore (similarly the access from Jean Zay to\\n  such machines also might not work).\\n\\nIn case of problems, contact the IDRIS Support.\\n\\nBest regards,\\nThe IDRIS user support team"},{"id":"flash-info-2024-12","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-12","source":"@site/blog/2024/2024-05-31-flash-info-12.md","title":"Flash Info de l\'IDRIS n\xb02024-12","description":"JupyterHub : Nouvelle interface de connexion \xe0 partir du mardi 4 juin 2024","date":"2024-05-31T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-12","title":"Flash Info de l\'IDRIS n\xb02024-12","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-13","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-13"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-11","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-11"}},"content":"JupyterHub : Nouvelle interface de connexion \xe0 partir du mardi 4 juin 2024\\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nA partir du mardi 4 juin 2024, la connexion \xe0 JupyterHub se fera via le service d\'authentification\\ncentralis\xe9e de l\'IDRIS. Seule l\'interface de connexion change, le nom d\'utilisateur et le mot de passe\\nsont toujours ceux que vous utilisez pour vous connectez \xe0 la machine Jean Zay.\\n\\nLors de votre connexion \xe0 notre instance JupyterHub, vous devrez cliquer sur \\"Sign in with Jean Zay SSO\\"\\net suivre les instructions d\xe9crites dans notre documentation :\\nhttp://www.idris.fr/jean-zay/pre-post/jean-zay-jupyterhub.html#nouvelle_interface_de_connexion_a_partir_du_mardi_4_juin_2024.\\n\\nBien cordialement,\\nL\'\xe9quipe assistance de l\'IDRIS\\n\\n--------------------------------------------------\\n\\nHello,\\n\\nStarting from Tuesday, June 4th, 2024, the connection to our JupyterHub instance will use IDRIS\\nSingle Sign-on. The user interface will be different but your login and password are still the\\nsame as those for accessing the Jean Zay machine.\\n\\nWhen accessing our JupyterHub instance, you will need to click on \\"Sign in with Jean Zay SSO\\"\\nand follow the instructions described in our documentation:\\nhttp://www.idris.fr/eng/jean-zay/pre-post/jean-zay-jupyterhub-eng.html#new_authentication_interface_starting_from_tuesday_june_4th_2024.\\n\\nBest regards,\\nThe IDRIS user support team"},{"id":"flash-info-2024-11","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-11","source":"@site/blog/2024/2024-05-23-flash-info-11.md","title":"Flash Info de l\'IDRIS n\xb02024-11","description":"Sommaire :","date":"2024-05-23T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-11","title":"Flash Info de l\'IDRIS n\xb02024-11","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-12","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-12"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-10","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-10"}},"content":"Sommaire : \\n- La 2\xe8me Journ\xe9e Deep Learning pour la Science, c\'est demain !\\n- Formations IDRIS \\n\\n\\n* La 2\xe8me Journ\xe9e Deep Learning pour la Science, c\'est demain !\\n\\nLa deuxi\xe8me \xe9dition de la Journ\xe9e Deep Learning pour la Science (JDLS) a lieu demain, le 24 mai 2024 au si\xe8ge du CNRS \xe0 Paris. Retrouvez le programme et toutes les informations sur http://www.idris.fr/annonces/jdls2024.html. Les inscriptions sont closes mais la journ\xe9e sera retransmise en live sur la cha\xeene YouTube de Fidle : https://www.youtube.com/@CNRS-FIDLE (sans inscription n\xe9cessaire).\\n\\n* Formations IDRIS \\n\\nPensez \xe0 vous inscrire d\xe8s maintenant aux formations IDRIS planifi\xe9es jusqu\'\xe0 fin juin :\\n\\n - C++ Scientifique Moderne, du 3 au 5 juin\\n - Workshop Jean Zay, les 6 et 7 juin\\n\\nPour plus d\'informations sur le catalogue 2024 des formations de l\'IDRIS et les modalit\xe9s d\'inscription : http://www.idris.fr/formations/catalogue.html \\n\\n--------------------------------------------------------------------"},{"id":"flash-info-2024-10","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-10","source":"@site/blog/2024/2024-05-06-flash-info-10.md","title":"Flash Info de l\'IDRIS n\xb02024-10","description":"Sommaire :","date":"2024-05-06T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-10","title":"Flash Info de l\'IDRIS n\xb02024-10","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-11","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-11"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-09","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-09"}},"content":"Sommaire :\\nInformation relative aux sauvegardes des espaces disques sur Jean Zay\\nTaille maximale par fichier sur les espaces disques de Jean Zay \\nInscriptions pour la 2\xe8me Journ\xe9e Deep Learning pour la Science\\nFormations IDRIS \\n\\n\\n* Information relative aux sauvegardes des espaces disques sur Jean Zay \\n\\nEn raison des op\xe9rations li\xe9es \xe0 l\'arriv\xe9e de l\'extension H100, nous ne sommes plus en mesure de garantir les sauvegardes de l\'espace disque WORK (http://www.idris.fr/jean-zay/cpu/jean-zay-cpu-calculateurs-disques.html#les_sauvegardes). \xc0 terme, cette fonctionnalit\xe9 dispara\xeetra compl\xe8tement puisque la nouvelle technologie de syst\xe8me de fichiers parall\xe8le Lustre qui sera mise en place ne la fournira pas.\\n\\n* Taille maximale par fichier sur les espaces disques de Jean Zay \\n\\nPour des raisons techniques, nous allons prochainement limiter la taille maximale par fichier \xe0 10 Tio sur les espaces disques de Jean Zay. Nous vous invitons \xe0 vous conformer d\xe8s \xe0 pr\xe9sent \xe0 cette limite. \\n\\n* Inscriptions pour la 2\xe8me Journ\xe9e Deep Learning pour la Science \\n\\nLa deuxi\xe8me \xe9dition de la Journ\xe9e Deep Learning pour la Science (JDLS) aura lieu le 24 mai 2024 au si\xe8ge du CNRS \xe0 Paris. Si vous souhaitez venir en pr\xe9sentiel, il faut vous inscrire d\xe8s maintenant sur https://jdls-2024.sciencesconf.org/. Vous pouvez \xe9galement venir pr\xe9senter un poster et/ou participer \xe0 la session \\"Mon projet en 3 minutes\\", il suffit de nous contacter \xe0 jdls@idris.fr ou de d\xe9poser directement votre candidature sur https://jdls-2024.sciencesconf.org/submission/submit. La journ\xe9e sera retransmise en live sur la cha\xeene YouTube de Fidle (https://www.youtube.com/@CNRS-FIDLE). Si vous souhaitez seulement suivre le live \xe0 distance, aucune inscription n\'est demand\xe9e.\\n\\n* Formations IDRIS \\n\\nPensez \xe0 vous inscrire d\xe8s maintenant aux formations IDRIS planifi\xe9es jusqu\'\xe0 fin juin :\\n\\n - C++ Scientifique Moderne, du 3 au 5 juin\\n - Workshop Jean Zay, les 6 et 7 juin\\n - Deep Learning Optimis\xe9 sur Jean Zay, du 11 au 14 juin\\n - OpenMP / MPI, du 17 au 21 juin\\n - Introduction \xe0 OpenACC et OpenMP GPU, du 26 au 28 juin.\\n\\nPour plus d\'informations sur le catalogue 2024 des formations de l\'IDRIS et les modalit\xe9s d\'inscription : http://www.idris.fr/formations/catalogue.html \\n\\n--------------------------------------------------------------------"},{"id":"flash-info-2024-09","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-09","source":"@site/blog/2024/2024-04-30-flash-info-09.md","title":"Flash Info de l\'IDRIS n\xb02024-09","description":"R\xe9duction transitoire de la capacit\xe9 de stockage du SCRATCH","date":"2024-04-30T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-09","title":"Flash Info de l\'IDRIS n\xb02024-09","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-10","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-10"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-08","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-08"}},"content":"R\xe9duction transitoire de la capacit\xe9 de stockage du SCRATCH\\n\\n\\n[English version below]\\n\\nBonjour,\\n\\nComme annonc\xe9 r\xe9cemment, l\'arriv\xe9e de l\'extension H100 de Jean Zay s\'accompagnera du renouvellement de\\nses espaces de stockage. Afin de pr\xe9parer cette \xe9volution technique, la capacit\xe9 de l\'espace SCRATCH\\n(3,4 Pio) a d\xfb \xeatre r\xe9duite d\'environ un tiers ce qui correspond approximativement \xe0 un retour \xe0 la\\ncapacit\xe9 disponible avant la derni\xe8re extension de cet espace courant 2023. Cette situation perdurera\\njusqu\'\xe0 la mise en service du nouvel espace SCRATCH de 4,6 Pio, au plus tard en septembre 2024.\\n\\nNous vous invitons donc \xe0 faire r\xe9guli\xe8rement du m\xe9nage dans votre SCRATCH lorsque cela est possible.\\nVous pouvez par exemple supprimer les donn\xe9es dont vous n\'avez plus besoin ou d\xe9placer celles que vous\\nn\'allez pas r\xe9utiliser prochainement vers les espaces WORK ou STORE (en regroupant les fichiers dans\\ndes archives \\"tar\\" si n\xe9cessaire, sans d\xe9passer 10 Tio par fichier).\\n\\nBien cordialement,\\nL\'\xe9quipe assistance de l\'IDRIS\\n\\n--------------------------------------------------\\n\\nHello,\\n\\nAs recently announced, the new H100 extension of Jean Zay will be accompanied by the renewal of\\nJean Zay\'s storage spaces. In order to prepare this technical change, the capacity of the SCRATCH\\nfilesystem (3.4 PiB) had to be reduced by about a third which corresponds approximately to going\\nback to the capacity available before the latest extension of that disk space in 2023. The new\\nSCRATCH filesystem of 4.6 PiB will be available in September 2024 at the latest.\\n\\nWe invite you to clean up your SCRATCH space regularly whenever possible. You can for example remove\\nunused data or move data that you will not use in the near future to the WORK or STORE storage spaces\\n(regrouping files in \\"tar\\" archives when necessary, without going over 10 TiB per file).\\n\\nBest regards,\\nThe IDRIS user support team"},{"id":"flash-info-2024-08","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-08","source":"@site/blog/2024/2024-04-17-flash-info-08.md","title":"Flash Info de l\'IDRIS n\xb02024-08","description":"Sommaire :","date":"2024-04-17T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-08","title":"Flash Info de l\'IDRIS n\xb02024-08","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-09","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-09"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-07","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-07"}},"content":"Sommaire :\\nInscriptions ouvertes pour la 2de Journ\xe9e Deep Learning pour la Science\\nFormations IDRIS\\n\\n* Inscriptions ouvertes pour la 2de Journ\xe9e Deep Learning pour la Science\\n\\nLa deuxi\xe8me \xe9dition de la Journ\xe9e Deep Learning pour la Science (JDLS) aura lieu le 24 mai 2024 au si\xe8ge\\ndu CNRS \xe0 Paris. Si vous souhaitez venir en pr\xe9sentiel, il faut vous inscrire d\xe8s maintenant sur \\nhttps://jdls-2024.sciencesconf.org/. Vous pouvez \xe9galement venir pr\xe9senter un poster et/ou participer \xe0 la\\nsession \\"Mon projet en 3 minutes\\", il suffit de nous contacter \xe0 jdls@idris.fr ou de d\xe9poser directement\\nvotre candidature sur https://jdls-2024.sciencesconf.org/submission/submit. La journ\xe9e sera retransmise \\nen live sur la cha\xeene YouTube de Fidle (https://www.youtube.com/@CNRS-FIDLE). Si vous souhaitez seulement\\nsuivre le live \xe0 distance, aucune inscription n\'est demand\xe9e.\\n\\n* Formations IDRIS\\n\\nPensez \xe0 vous inscrire d\xe8s maintenant aux formations IDRIS planifi\xe9es jusqu\'\xe0 fin juin :\\n  - Programmation Hybride MPI/OpenMP, les 30 et 31 mai\\n  - C++ Scientifique Moderne, du 3 au 5 juin\\n  - Workshop Jean Zay, les 6 et 7 juin\\n  - Deep Learning Optimis\xe9 sur Jean Zay, du 11 au 14 juin\\n  - OpenMP / MPI, du 17 au 21 juin\\n  - Introduction \xe0 OpenACC et OpenMP GPU, du 26 au 28 juin.\\n\\nPour plus d\'informations sur le catalogue 2024 des formations de l\'IDRIS et les modalit\xe9s d\'inscription :\\nhttp://www.idris.fr/formations/catalogue.html\\n\\n--------------------------------------------------------------------"},{"id":"flash-info-2024-07","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-07","source":"@site/blog/2024/2024-04-04-flash-info-07.md","title":"Flash Info de l\'IDRIS n\xb02024-07","description":"Sommaire :","date":"2024-04-04T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-07","title":"Flash Info de l\'IDRIS n\xb02024-07","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-08","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-08"},"nextItem":{"title":"Extension H100 de Jean Zay","permalink":"/documentation/idris-documentation-docusaurus/blog/extension-h100-jean-zay"}},"content":"Sommaire :\\nPanoram\'IA : rendez-vous demain, vendredi 5 avril \xe0 10h\\nFormations IDRIS\\n\\n* Panoram\'IA : rendez-vous demain, vendredi 5 avril \xe0 10h\\n\\nL\'assistance de l\'IDRIS vous propose demain matin, vendredi 05/04 \xe0 10h, \\"Panoram\'IA\\" : le magazine vid\xe9o\\nmensuel et en direct qui aborde l\'actualit\xe9 scientifique et technique de l\'IA. Au programme de cette\\nsession : les br\xe8ves de l\'IA, optimisation m\xe9moire sur GPU pour les LLMs, alignement de mod\xe8le et notre\\ns\xe9lection de papier avec Papers Storm.\\nLe direct ainsi que les rediffusions sont disponibles sur notre cha\xeene Youtube \\"Un oeil sur l\'IDRIS\\" :\\nhttps://www.youtube.com/@idriscnrs.\\nLes sessions suivantes auront lieu les 03/05/2024 et 21/06/2024.\\n\\n* Formations IDRIS\\n\\nPensez \xe0 vous inscrire d\xe8s maintenant aux formations IDRIS planifi\xe9es jusqu\'\xe0 fin juin :\\n  - Programmation Hybride MPI/OpenMP, les 30 et 31 mai\\n  - C++ Scientifique Moderne, du 3 au 5 juin\\n  - Workshop Jean Zay, les 6 et 7 juin\\n  - Deep Learning Optimis\xe9 sur Jean Zay, du 11 au 14 juin\\n  - OpenMP / MPI, du 17 au 21 juin\\n  - Introduction \xe0 OpenACC et OpenMP GPU, du 26 au 28 juin.\\n\\nPour plus d\'informations sur le catalogue 2024 des formations de l\'IDRIS et les modalit\xe9s d\'inscription :\\nhttp://www.idris.fr/formations/catalogue.html\\n\\n--------------------------------------------------------------------"},{"id":"extension-h100-jean-zay","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/extension-h100-jean-zay","source":"@site/blog/2024/2024-03-28-extension-h100-jean-zay.md","title":"Extension H100 de Jean Zay","description":"1456 GPU H100 pour franchir la barre des 125 PFlop/s","date":"2024-03-28T00:00:00.000Z","tags":[{"inline":false,"label":"actu","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/actu","description":"Les actualit\xe9s diverses de l\'IDRIS."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"extension-h100-jean-zay","title":"Extension H100 de Jean Zay","authors":["idris"],"tags":["actu"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-07","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-07"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-06","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-06"}},"content":"***1456 GPU H100 pour franchir la barre des 125 PFlop/s***\\n\\nGENCI et le CNRS choisissent Eviden pour faire du supercalculateur Jean Zay l\u2019une des machines les plus puissantes de France.\\n\\nDans le prolongement de l\u2019annonce du Pr\xe9sident de la R\xe9publique lors de Vivatech en juin 2023, le Grand Equipement National de Calcul Intensif (GENCI) et le Centre national de la recherche scientifique (CNRS), sous la houlette du minist\xe8re de l\u2019Enseignement sup\xe9rieur et de la Recherche, ont s\xe9lectionn\xe9 Eviden pour fournir une extension majeure des capacit\xe9s du supercalculateur Jean Zay, financ\xe9e dans le cadre de France 2030.\\n\\nCette annonce marque une nouvelle \xe9tape pour l\u2019IA souveraine.\\n\\nUn communiqu\xe9 de presse officiel est publi\xe9 sur le site du CNRS :\\nhttps://www.cnrs.fr/fr/presse/genci-et-le-cnrs-choisissent-eviden-pour-faire-du-supercalculateur-jean-zay-lune-des\\n\\nVoici [les nouvelles caract\xe9ristiques du supercalculateur Jean Zay](/img/blog/2024/jz4-plaquette.pdf) suite \xe0 cette extension :\\n\\n[![jz-plaquette-3pages](/img/blog/2024/jz4-plaquette-3pages.png)](/img/blog/2024/jz4-plaquette.pdf)\\n\\nCalendrier pr\xe9visionnel de mise en service de l\'extension H100 de Jean Zay :\\n\\n![calendrier-mise-en-service-jz4](/img/blog/2024/calendrier-mise-en-service-jz4.png)"},{"id":"flash-info-2024-06","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-06","source":"@site/blog/2024/2024-03-20-flash-info-06.md","title":"Flash Info de l\'IDRIS n\xb02024-06","description":"Sommaire :","date":"2024-03-20T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-06","title":"Flash Info de l\'IDRIS n\xb02024-06","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Extension H100 de Jean Zay","permalink":"/documentation/idris-documentation-docusaurus/blog/extension-h100-jean-zay"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-05","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-05"}},"content":"Sommaire :\\n\\nProchaine r\xe9union du CU de l\'IDRIS : mardi 2 avril 2024\\nProchaine session WORKSHOP Jean Zay(6-7 juin 2024)\\nNouvelle formation : C++ Scientifique Moderne\\nAgenda des formations IDRIS\\n\\n* Prochaine r\xe9union du CU de l\'IDRIS : mardi 2 avril 2024\\nLa prochaine r\xe9union du Comit\xe9 des utilisateurs (CU) de l\'IDRIS aura lieu le 2 avril 2024 dans les locaux \\nde l\'IDRIS. N\'h\xe9sitez pas \xe0 transmettre vos demandes \xe0 l\'adresse : cu-elus at idris.fr. Plus d\'information :\\n http://www.idris.fr/cu.html\\n\\n* Prochaine session WORKSHOP Jean Zay (6-7 juin 2024)\\nCette session s\'adresse \xe0 tous les utilisateurs, aussi bien les d\xe9butants qui souhaitent travailler rapidement sur Jean Zay ou les plus exp\xe9riment\xe9s pour optimiser leurs applications. \\nPr\xe9requis: il est n\xe9cessaire d\'avoir un compte ou une demande de compte en cours sur la machine Jean Zay pour assister \xe0 la session.\\nPour plus d\'informations : http://www.idris.fr/formations/workshop-jz/fiche-workshop-jz.html \\n\\n* Nouvelle formation : C++ Scientifique Moderne (3-5 juin 2024)\\nLa formation s\'adresse aux utilisateurs qui souhaitent se mettre \xe0 jour sur les nouveaut\xe9s du langage C++ et de sa biblioth\xe8que standard.\\nPour plus d\'informations : http://www.idris.fr/formations/cplusplus/fiche-cplusplus.html\\n\\n* Agenda des formations IDRIS\\n\\nPensez \xe0 vous inscrire d\xe8s maintenant aux formations IDRIS planifi\xe9es jusqu\'\xe0 fin juin :\\n  - Programmation Hybride MPI/OpenMP, les 30 et 31 mai\\n  - C++ Scientifique Moderne, du 3 au 5 juin\\n  - Workshop Jean Zay, les 6 et 7 juin\\n  - Deep Learning Optimis\xe9 sur Jean Zay, du 11 au 14 juin\\n  - OpenMP / MPI, du 17 au 21 juin\\n  - Introduction \xe0 OpenACC et OpenMP GPU, du 26 au 28 juin.\\n\\nPour plus d\'informations sur le catalogue 2024 des formations de l\'IDRIS et les modalit\xe9s d\'inscription : http://www.idris.fr/formations/catalogue.html"},{"id":"flash-info-2024-05","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-05","source":"@site/blog/2024/2024-02-16-flash-info-05.md","title":"Flash Info de l\'IDRIS n\xb02024-05","description":"* Maintenance le mercredi 21 f\xe9vrier 2024","date":"2024-02-16T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-05","title":"Flash Info de l\'IDRIS n\xb02024-05","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-06","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-06"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-04","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-04"}},"content":"* Maintenance le mercredi 21 f\xe9vrier 2024\\n\\nSuite \xe0 une maintenance d\'infrastructure, les partitions CPU, quadri GPU V100 et octo-GPU V100 seront\\nindisponibles le mercredi 21 f\xe9vrier 2024 de 07h00 \xe0 20h00. Seuls les jobs sur la partition A100 pourront\\ns\'ex\xe9cuter entre 10h et 16h, et les acc\xe8s interactifs resteront possibles pendant cette p\xe9riode.\\n\\nNous vous prions de nous excuser pour la g\xeane occasionn\xe9e.\\n\\n\\n--------------------------------------------------------------------"},{"id":"flash-info-2024-04","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-04","source":"@site/blog/2024/2024-02-14-flash-info-04.md","title":"Flash Info de l\'IDRIS n\xb02024-04","description":"Sommaire :","date":"2024-02-14T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-04","title":"Flash Info de l\'IDRIS n\xb02024-04","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-05","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-05"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-03","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-03"}},"content":"Sommaire :\\nPanoram\'IA : rendez-vous vendredi 16 f\xe9vrier \xe0 10h\\nRemise en production de la partition gpu_p2\\nFormations IDRIS\\n\\n* Panoram\'IA : rendez-vous vendredi 16 f\xe9vrier \xe0 10h\\n\\nL\'assistance de l\'IDRIS vous propose \\"Panoram\'IA\\" : un magazine vid\xe9o mensuel et en direct qui aborde\\nl\'actualit\xe9 scientifique et technique de l\'IA. \\nLe direct ainsi que les rediffusions sont disponibles sur notre cha\xeene Youtube \\"Un oeil sur l\'IDRIS\\" :\\nhttps://www.youtube.com/@idriscnrs. \\nLes sessions suivantes auront lieu les 15/03/2024 et 05/04/2024.\\n\\n* Remise en production de la partition gpu_p2\\n\\nLa partition gpu_p2 qui avait \xe9t\xe9 retir\xe9e de la production le 05/02 est \xe0 nouveau op\xe9rationnelle. Elle\\nest dor\xe9navant accessible \xe0 tous les utilisateurs ayant demand\xe9 des heures V100 sur Jean Zay, quelque\\nsoit leur comit\xe9 th\xe9matique. Pour rappel, il s\'agit de 31 n\u0153uds contenant chacun 24 c\u0153urs CPU Intel\\nCascade Lake (384 Go ou 768 Go) et 8 GPU V100 32Go :\\nhttp://www.idris.fr/jean-zay/cpu/jean-zay-cpu-hw.html#gpu_p2.\\n\\n* Formations IDRIS\\n\\nPensez \xe0 vous inscrire d\xe8s maintenant aux formations IDRIS planifi\xe9es jusqu\'en avril :\\n     - MPI, du 12 au 15 mars 2024\\n     - OpenMP, du 20 au 22 mars 2024\\n     - Introduction aux librairies ScaLAPACK et MAGMA, les 3 et 4 avril 2024\\n     - Vectorisation SIMD, le 5 avril 2024\\n\\nPour plus d\'informations sur le catalogue 2024 des formations de l\'IDRIS et les modalit\xe9s d\'inscription :\\nhttp://www.idris.fr/formations/catalogue.html\\n\\n--------------------------------------------------------------------"},{"id":"flash-info-2024-03","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-03","source":"@site/blog/2024/2024-02-01-flash-info-03.md","title":"Flash Info de l\'IDRIS n\xb02024-03","description":"\\"Bootcamp AI for Science\\" \xe0 l\'IDRIS le 23 mai 2024 - Plus que quelques jours pour vous inscrire","date":"2024-02-01T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-03","title":"Flash Info de l\'IDRIS n\xb02024-03","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-04","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-04"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-02","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-02"}},"content":"\\"Bootcamp AI for Science\\" \xe0 l\'IDRIS le 23 mai 2024 - Plus que quelques jours pour vous inscrire\\n\\n\\n[English version below]\\n\\nNous vous rappelons que le \\"Bootcamp AI for Science\\" organis\xe9 par l\'IDRIS en collaboration avec NVIDIA\\naura lieu le 23 mai 2024 en pr\xe9sentiel \xe0 l\'IDRIS. Il sera donn\xe9 en anglais.\\n\\nCe bootcamp vise \xe0 donner un aper\xe7u pas-\xe0-pas des notions fondamentales de l\'apprentissage profond, \xe0\\npermettre aux participants de construire et d\'am\xe9liorer des mod\xe8les d\'apprentissage profond au travers\\nd\'exercices pratiques bas\xe9s sur un framework utilisant les lois fondamentales de la physique pour mod\xe9liser\\nle comportement de syst\xe8mes complexes.\\n\\nInscription sur https://www.openhackathons.org/s/siteevent/a0C5e000008AcVSEA0 jusqu\'au 6 f\xe9vrier 2024.\\n\\nNotez que la deuxi\xe8me \xe9dition de la Journ\xe9e Deep Learning pour la Science, coanim\xe9e par FIDLE, l\'IDRIS et\\nle PNRIA, aura lieu le lendemain, vendredi 24 mai 2024, au Grand Auditorium du CNRS, \xe0 Paris Michel-Ange.\\n\\n--------\\n\\nWe remind you that the AI for Science Bootcamp organized by IDRIS together with NVIDIA will be held\\non May 23rd 2024 on site at IDRIS.\\n\\nThis bootcamp provides a step-by-step overview of the fundamentals of deep neural networks, walks\\nattendees through the hands-on experience of building and improving deep learning models using a\\nframework that uses the fundamental laws of physics to model the behavior of complex systems.\\n\\nThe deadline for registering is February 6th, 2024.\\nRegistration on https://www.openhackathons.org/s/siteevent/a0C5e000008AcVSEA0.\\n\\nPlease note that the second edition of the \u201cJourn\xe9e Deep Learning pour la Science\u201d, organized\\nby FIDLE, IDRIS and the PNRIA, will take place on May 24th 2024, at the \u201cGrand Auditorium\u201d\\nof CNRS headquarters (Paris Michel-Ange)."},{"id":"flash-info-2024-02","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-02","source":"@site/blog/2024/2024-01-10-flash-info-02.md","title":"Flash Info de l\'IDRIS n\xb02024-02","description":"(English version below)","date":"2024-01-10T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-02","title":"Flash Info de l\'IDRIS n\xb02024-02","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-03","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-03"},"nextItem":{"title":"Flash Info de l\'IDRIS n\xb02024-01","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-01"}},"content":"(English version below)\\n\\nHackathon GPU HPC et IA \xe0 l\'IDRIS - Plus que quelques jours pour vous inscrire\\n\\nNous vous rappelons que le hackathon GPU HPC et IA 2024 organis\xe9 conjointement par l\'IDRIS et NVIDIA, aura lieu le 18 mars (\xe0 distance) et les 25, 26 et 27 avril 2023 (dans les locaux de l\'IDRIS). \\n\\nLa date limite d\'inscription est le 24 janvier 2024.\\n\\nPour plus d\'informations et/ou vous inscrire, consultez la page de l\'\xe9v\xe8nement (en anglais) :\\n  https://www.openhackathons.org/s/siteevent/a0C5e000008ncD5EAI/se000222.\\n\\n---------------------\\n\\nHPC and AI GPU Hackathon at IDRIS - Only a few days left to register\\n\\nWe remind you that the HPC and AI GPU 2024 Hackathon organized together by IDRIS and NVIDIA will be held on March 18th (remotely) and from March 25th through March 27th (on site at IDRIS).\\n\\nThe application deadline is 24th January 2024.\\n\\nPlease register on https://www.openhackathons.org/s/siteevent/a0C5e000008ncD5EAI/se000222."},{"id":"flash-info-2024-01","metadata":{"permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-01","source":"@site/blog/2024/2024-01-05-flash-info-01.md","title":"Flash Info de l\'IDRIS n\xb02024-01","description":"Sommaire :","date":"2024-01-05T00:00:00.000Z","tags":[{"inline":false,"label":"flashinfo","permalink":"/documentation/idris-documentation-docusaurus/blog/tags/flashinfo","description":"Le Flash Info est la lettre \xe9lectronique envoy\xe9e \xe0 tous les utilisateurs de l\'IDRIS. Son objectif est d\'informer ses lecteurs des derni\xe8res nouveaut\xe9s concernant l\'IDRIS. Son rythme de parution d\xe9pend de l\'information \xe0 diffuser."}],"hasTruncateMarker":false,"authors":[{"name":"IDRIS","title":"Computing center","imageURL":"https://upload.wikimedia.org/wikipedia/fr/7/72/Logo_Centre_national_de_la_recherche_scientifique_%282023-%29.svg","key":"idris","page":null}],"frontMatter":{"slug":"flash-info-2024-01","title":"Flash Info de l\'IDRIS n\xb02024-01","authors":["idris"],"tags":["flashinfo"]},"unlisted":false,"prevItem":{"title":"Flash Info de l\'IDRIS n\xb02024-02","permalink":"/documentation/idris-documentation-docusaurus/blog/flash-info-2024-02"}},"content":"Sommaire :\\nVoeux 2024\\nRappel : 4 postes \xe0 pourvoir dans le cadre de la campagne de mobilit\xe9 interne CNRS (NOEMI/FSEP)\\nFormation IPDL : modifications du cursus\\nRappel : Hackathon 2024 GPU HPC/IA en mars prochain\\nRappel : \\"Bootcamp AI for Science\\" \xe0 l\'IDRIS le 23 mai 2024\\nFormations IDRIS\\n\\n* L\'IDRIS vous souhaite une tr\xe8s bonne ann\xe9e 2024 !\\n\\n\\n* Rappel : 4 postes \xe0 pourvoir dans le cadre de la campagne de mobilit\xe9 interne CNRS NOEMI-FSEP,\\n ouverte jusqu\'au 16 janvier 2024 inclus : \\n\\n     - un(e) ing\xe9nieur(e) en intelligence artificielle - fonction Y61019, IR.\\n     - un(e) assistant(e) en gestion administrative et en communication - fonction Y61020, AI.\\n     - un(e) gestionnaire d\'infrastructures - fonction Y61021, AI.\\n     - un(e)expert(e) en calcul scientifique - fonction Y61022, IR.\\n\\nPour plus d\'information sur ces postes : http://www.idris.fr/annonces/idris-recrute.html\\n\\n\\n* Formations \\"Introduction au Deep Learning\\"  : modification du cursus \\n\\nAfin de mieux adapter le contenu de la formation IPDL aux besoins et niveaux des participants,\\n cette formation a \xe9t\xe9 d\xe9comps\xe9e en deux formations cons\xe9cutives : \\n     - IPDL  : Introduction Pratique au Deep Learning, qui reprend la premi\xe8re partie du cours IPDL \\nhttp://www.idris.fr/formations/ipdl/fiche-ipdl.html \\n     - ArchDL  : Architectures du Deep Learning, qui propose les partie plus avanc\xe9es \\nhttp://www.idris.fr/formations/archdl/fiche-archdl.html \\nLes futurs stagiaires peuvent s\'inscrire \xe0 l\'une et/ou l\'autre de ces sessions selon leurs besoins\\n et niveaux. \\nLes prochaines dates : \\n     - Introduction pratique au deep learning (IPDL), les 5 et 6 f\xe9vrier 2024\\n     - Architectures du deep learning (ArchDL), les 7 et 8 f\xe9vrier 2024\\n     - Atelier de lancement en deep learning (ALDL), le 9 f\xe9vrier 2024\\n\\nPour plus d\'information et pour vous inscrire, consultez notre site web : \\nhttps://cours.idris.fr\\n\\n\\n* Rappel : Hackathon GPU HPC/IA en mars prochain\\n\\nNous vous rappelons que vous avez jusqu\'au 15 janvier prochain pour vous inscrire au hackathon\\n GPU HPC/IA qui aura lieu fin mars 2024 \xe0 l\'IDRIS : \\nhttp://www.idris.fr/annonces/idris-gpu-hackathon-2024.html.\\n\\n\\n* Rappel : \\"Bootcamp AI for Science\\" \xe0 l\'IDRIS le 23 mai 2024\\n\\nL\'IDRIS organise un \\"Bootcamp AI for Science\\" en collaboration avec NVIDIA le 23 mai 2024 \\nen pr\xe9sentiel \xe0 l\'IDRIS. Pour plus d\'information sur cet \xe9v\xe8nement et pour vous inscrire \\navant le 1er f\xe9vrier prochain :https://www.openhackathons.org/s/siteevent/a0C5e000008AcVSEA0 \\n\\n\\n* Formations IDRIS \\n\\nPensez \xe0 vous inscrire d\xe8s maintenant aux formations IDRIS planifi\xe9es jusqu\'en avril :\\n     - MPI, du 12 au 15 mars 2024\\n     - OpenMP, du 20 au 22 mars 2024\\n     - Introduction aux librairies ScaLAPACK et MAGMA, les 3 et 4 avril 2024\\n     - Vectorisation SIMD, le 5 avril 2024\\n\\nPour plus d\'informations sur le catalogue 2024 des formations de l\'IDRIS et les modalit\xe9s\\n d\'inscription : http://www.idris.fr/formations/catalogue.html"}]}}')}}]);